(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["da"] = {"ui":{"skip":"Spring til indhold","back":"← Tilbage til AI-gile","lang.button":"Sprog: {name}","lang.dialog":"Vælg et sprog","lang.search":"Søg efter sprog","lang.none":"Intet sprog passer","lang.notYet":"{name} er ikke oversat endnu","theme.aria":"Skift tema: lyst, mørkt eller sort","theme.toLight":"Skift til lyst tema","theme.toDark":"Skift til mørkt tema","theme.toBlack":"Skift til sort tema (helt sort, skånsomt for OLED-skærme)","words.underline":"Understreg disse ord på siden","words.underlineHelp":"Hold musen over eller tryk på et prikket ord for at se, hvad det betyder.","words.col.todo":"Kort valgt til nu: teamet går i gang med disse som de næste.","words.col.doing":"En AI arbejder på dette kort lige nu.","words.col.review":"Én AI har lavet arbejdet; en anden tjekker det, før det når dig.","words.col.verify":"Venter på dig: prøv det af og sig, om det virker.","words.col.team":"Dine noter eller svar, der venter på, at teamet henter dem.","words.col.done":"Færdigt og godkendt.","index.title":"AI-gile: dit AI-udviklerteam på ét board","index.description":"AI-gile er et kanban-board til AI-kodeteams. De arbejder, mens du sover; du får én kort bunke ting at beslutte, teste og godkende.","hero.logoAlt":"AI-gile board-ikon","hero.h1.html":"Dit AI-udviklerteam på ét&nbsp;board.","hero.alpha":"🐣 Lukket pre-alfa","hero.alphaTitle":"Tidligt og ufærdigt: tak, fordi du prøver det!","hero.lede":"De bygger, mens du sover. Du vågner op til én kort bunke: et par spørgsmål, et par ting at teste, en lilla diamant eller to. Klik, godkend, tilbage til din kaffe.","dl.windows":"Windows-app","dl.browser":"Kør det i din browser","dl.messenger":"📱 Messenger til din telefon","dl.soon":"Kommer snart","dl.notify":"🔔 Giv mig besked, når det åbner","dl.notifySmall":"Alfa eller beta","hero.secondary":"Agile, men teamet har aldrig brug for en stand-up-kaffe. (De holder stand-ups alligevel.)","pitch.h2":"AI-gile på lige så mange ord, som du vil","pitch.lede":"Vælg en længde, fra ét ord til 144. Hver længde er sin egen beskrivelse, skrevet til netop den størrelse. Træk i skyderen eller brug piletasterne.","pitch.rangeLabel":"Længde i ord","pitch.dice":"🎲 en anden version","pitch.words.one":"{n} ord","pitch.words.other":"{n} ord","pitch.letters.one":"{n} bogstav","pitch.letters.other":"{n} bogstaver","pitch.chars.one":"{n} tegn","pitch.chars.other":"{n} tegn","count.line.html.one":"{n} kort på boardet lige nu","count.line.html.other":"{n} kort på boardet lige nu","people.humans.html.one":"👥 {n} menneske","people.humans.html.other":"👥 {n} mennesker","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenter","people.working.html.one":"⚡ {n} i gang lige nu","people.working.html.other":"⚡ {n} i gang lige nu","pre.title":"AI-gile: her bliver der bygget noget","pre.description":"Her bliver der bygget noget. Et board, hvor AI-teams bygger det, du beder om, og lærer dig noget undervejs. Lige nu en lukket pre-alfa med venner.","pre.h1":"Her bliver der bygget noget. 🤫","pre.line":"Et board, hvor AI-teams bygger det, du beder om, og lærer dig noget undervejs. Lige nu en lukket pre-alfa med venner.","pre.btn":"🔔 Giv mig besked, når det åbner","pre.peek":"Bag glasset: det rigtige board, live. Hvert kort er en farvet bjælke.","pre.peekFake":"Bag glasset: sådan ser et board i arbejde ud.","pre.night":"🌙 Nattevagten har styringen · 😴 mennesket hviler","features.aria":"Hvad det kan","f.pile.h":"Én bunke til dig","f.pile.html":"<b>Til dig</b> samler alt, der venter på dig, på tværs af alle projekter: spørgsmål, ting at teste, opgaver kun et menneske kan løse. Din kø fortæller, hvad der er næste skridt, og hvor lang tid det tager.","f.sleep.h":"Teams, der arbejder, mens du sover","f.sleep.p":"Hvert projekt har en lead og et team af AI-agenter. Skriv en kommentar på et kort, så vågner teamet, gør arbejdet og afleverer det tilbage med trin, som et træt menneske kan følge.","f.tester.h":"En AI-tester tjekker først","f.tester.p":"Før noget når frem til dig, følger en tester trinene i en kopi af appen og viser, hvad den så, med et skærmbillede. Bladr igennem de bestårede og godkend med ét klik.","f.proof.h":"Bevis, ikke løfter","f.proof.p":"Hver aflevering viser, hvad der er ændret: filerne, forskellene, skærmbillederne. Du behøver ikke åbne hver app for at se, om det er færdigt.","f.chat.h":"Chat med dine leads","f.chat.p":"En Discord-agtig bjælke: ét ikon pr. projekt, lilla diamanter ved det, der skal bruge dig. Skriv en idé til en lead; så laver de den om til kort og en plan, med en ✅ Go-knap.","f.tidy.h":"Holder selv orden","f.tidy.p":"Beslægtede kort smelter sammen, rodede titler bliver rettet, og et token-tjek holder koden slank. Færre ting at skifte mellem, mindre at tænke på.","f.private.h":"Dit, på din computer","f.private.li1":"Boardet kører på din egen maskine og svarer kun dig.","f.private.li2":"Private beskeder mellem mennesker er end-to-end-krypterede.","f.private.li3":"Ingen konti, ingen trackere, ingen cookies.","f.lang.h":"På dit sprog","f.lang.p":"Over 120 sprog, fra hollandsk, walisisk og japansk til pirat, Yoda og klingon, med et hurtigt skift tilbage til engelsk til fagsproget.","f.service.h":"Fra en idé til en rigtig service","f.service.p":"Har du bygget noget med AI, som folk nu bruger? Markér det som en service, så hjælper tavlen dig med at drive det godt: oppetidstjek, en offentlig statusside, hændelser med en opsamling, ændringer der kræver et Go, backups der tjekkes dagligt. Hjælp lærer dig hvert trin undervejs.","msgr.h2":"AI-gile Messenger: dit team i lommen","msgr.p1":"Tal med dit AI-team uden at åbne boardet. Chat med dine projektledere og dine venner, og se et korts teststeps og svar på dem, alt sammen fra din telefon.","msgr.p2":"Scan en QR-kode på dit board for at parre den. Første gang? En venlig demochat viser dig rundt.","msgr.when":"Android først, derefter en webversion til telefoner og iPhone.","msgr.who":"Din projektleder","msgr.b1":"Rettelsen til mørk tilstand er klar. Vil du have teststeps?","msgr.b2":"Ja tak!","msgr.b3":"1. Åbn Indstillinger. 2. Vælg Mørkt. Ser det rigtigt ud?","tl.aria":"Tidslinje fra den første samtale til køreplanen","tl.h2":"Fra den første chat til det, der kommer","tl.lede":"Rigtige datoer og tidspunkter i din egen tidszone. Efter i dag er det planen, uden lovede datoer.","tl.today":"I dag","tl.planned":"planlagt","tl.doing":"i gang","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vær med","join.lede":"AI-gile bygges af en skægget særling med AuDHD og et par kampe med det mentale helbred, og et stort antal tålmodige agenter. Det er privat for nu, i en lukket alfa med venner. Vil du prøve det, når det åbner?","join.btn":"Meld interesse","join.small":"Vi sender dig en mail, ikke andet","footer.tag":"AI-gile. Ingen trackere, ingen cookies, ingen stand-up-kaffe.","footer.licence":"Erhvervslicens","footer.status":"Status","footer.privacy":"Hvad vi gemmer","footer.thanks":"Opkald takket være ChilledChat","form.sending":"Sender…","form.failed":"Det virkede ikke: prøv igen senere.","form.offline":"Kunne ikke nå AI-gile: prøv igen senere.","form.keep":"Vi bruger det kun til at svare dig og sletter det så. Ingen trackere, ingen cookies.","form.keepLink":"Hvad vi gemmer","interest.title":"AI-gile: sig til, når alfaen åbner","interest.description":"Skriv din mail, så får du besked, når AI-giles lukkede alfa eller beta åbner.","interest.h1":"🔔 Giv mig besked, når det åbner","interest.lede":"AI-gile er i lukket pre-alfa. Skriv din mail, så skriver vi én gang, når der er en plads til dig.","interest.email":"Din mail","interest.which":"Hvilken test?","interest.alpha":"Lukket alfa: tidligt, groft, mange ændringer","interest.beta":"Beta: mere stabil, senere","interest.both":"Begge dele, hvad der kommer først","interest.submit":"Sæt mig på listen","interest.thanks":"Tak! Du er på listen.","licence.title":"AI-gile: erhvervslicens","licence.description":"Bruger du AI-gile i din virksomhed? Ansøg om en gratis erhvervslicens.","licence.h1":"📜 Erhvervslicens","licence.lede":"Bruger du AI-gile på arbejde? Fortæl os, hvem du er, og hvad du laver. Gør det noget godt, er licensen gratis.","licence.company":"Virksomhed","licence.website":"Hjemmeside","licence.what":"Hvad du laver","licence.how":"Hvordan det hjælper verden","licence.email":"Mail","licence.submit":"Ansøg","licence.thanks":"Tak! Vi svarer på mail.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Alt er roligt","status.intro":"Virker AI-gile lige nu? Denne side tjekker hjemmesiden, deling af boards, opkald og downloaden hvert 5. minut.","status.up":"Virker (svarede på {ms} ms)","status.slow":"Svarede ikke på sidste tjek, prøver igen","status.down":"Nede: svarede ikke på de sidste to tjek","status.svc.web":"Hjemmeside","status.svc.web.offers":"Denne side: hvad AI-gile er, og interesseformularen","status.svc.boards":"Deling af boards","status.svc.boards.offers":"Offentlige boards, beskeder mellem venner og invitationer","status.svc.calls":"Opkald","status.svc.calls.offers":"Tale, video og skærmdeling i AI-gile","status.svc.download":"Download","status.svc.download.offers":"Windows-installationsprogrammet og invitationslinks","status.checking":"Tjekker…","status.offline":"Kan ikke nå statustjenesten lige nu (prøver igen)","status.updated":"opdateret {ago}","status.justNow":"lige nu","status.min":"{n} min siden","status.hours":"{n} t siden","status.days":"{n} d siden","privacy.title":"AI-gile: hvad vi gemmer","privacy.h1":"Hvad vi gemmer","privacy.lede":"Kort fortalt: kun det, du sender os, og ikke ret længe.","privacy.only":"Kun det, du sender os: det, du skriver i en formular, fx din mail. Intet andet om dig.","privacy.sealed":"Det forsegles, så vores server ikke kan læse det: i din browser, før det sendes af sted (i en ældre browser i det øjeblik, det ankommer). Kun vores eget board kan åbne det.","privacy.server":"Det slettes fra serveren, så snart det når vores board. Alt, der stadig ligger der efter 30 dage, slettes alligevel.","privacy.board":"Vi gemmer det kun på vores board, indtil vi har svaret dig, og så sletter vi det også der.","privacy.none":"Ingen trackere, ingen cookies, ingen analyseværktøjer.","privacy.local":"Dit sprog og dit valg af lyst eller mørkt tema bliver i din egen browser. De sendes aldrig til os.","privacy.ask":"Vil du have det slettet før? Svar på vores mail, og sig det.","live.h2":"Se det blive bygget, live","live.caption":"Hvert kort er skjult: du ser arbejdets form, ikke ordene.","live.watching.one":"live: {n} kigger med","live.watching.other":"live: {n} kigger med","live.last.now":"Sidste kort flyttet lige nu","live.last.min.one":"Sidste kort flyttet for {n} min. siden","live.last.min.other":"Sidste kort flyttet for {n} min. siden","live.last.hour.one":"Sidste kort flyttet for {n} time siden","live.last.hour.other":"Sidste kort flyttet for {n} timer siden","live.last.day.one":"Sidste kort flyttet for {n} dag siden","live.last.day.other":"Sidste kort flyttet for {n} dage siden","live.offline":"Live-tavlen holder en lille pause. Kig forbi igen snart.","live.cols":"Backlog|To do|I gang|Teamet tjekker|Til dig at teste|Til teamet|Færdig","footer.models":"AI-gile sætter AI-modeller på arbejde for dig. Det, de siger og gør, er deres eget, så tjek det, før du stoler på det.","privacy.ai.h":"AI-delen","privacy.ai.models":"AI-gile er boardet. Arbejdet bliver gjort af AI-modeller fra andre firmaer, som Claude, Codex og Gemini, på dine egne konti.","privacy.ai.check":"Det, de skriver og gør, kommer fra dem, og det kan være forkert. Tjek det, før du bygger på det eller sender det ud.","privacy.ai.files":"De ændrer filer og kører kommandoer i de mapper, du forbinder. Tag en backup.","privacy.ai.send":"Det, du giver en model, går til firmaet, der driver den, på deres vilkår. Hvert firmas egne vilkår og priser gælder.","privacy.ai.asis":"AI-gile er en tidlig testversion, som den er."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotter.","Uddelegeret."]},{"n":2,"texts":["Robotternes kanban.","Agenter, organiseret.","Idéer, bygget."]},{"n":3,"texts":["Kanban for robotter.","Idéer bliver til funktioner.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-board drevet af AI-agenter.","Du skriver kort. Agenter bygger.","Gratis, lokalt, testet, lidt fjollet."]},{"n":8,"texts":["Et gratis kanban-board, hvor AI-agenter gør arbejdet.","Skriv en idé. Agenter bygger den. Du godkender.","Agile til ét menneske og mange tålmodige robotter."]},{"n":13,"texts":["Et kanban-board på din computer, hvor AI-agenter tager kortene op.","Skriv en idé. Et team af agenter bygger den. En tester tjekker den.","Gratis, ingen konti, ingen trackere: et board, nogle robotter og dig som chef."]},{"n":21,"texts":["AI-gile er et kanban-board til arbejde med AI-kodeagenter. De tager kortene op; du tester og godkender dem.","Hvert projekt får en lead og et team af AI-agenter. Skriv en kommentar på et hvilket som helst kort, så går teamet i gang.","Et gratis, personligt to do-board, der kører på din egen computer. Arbejderne er robotter. Den, der siger ja, er dig."]},{"n":34,"texts":["Du lægger idéer på et board. Et team af AI-agenter gør dem til virkende funktioner, tester dem og afleverer dem tilbage med trin, du kan prøve. Intet tæller som færdigt, før du siger det.","AI-gile er et hjemmelavet kanban-board, som Rich har bygget med masser af hjælp fra de agenter, det nu styrer. Det er gratis, kører på din computer og deles med venner, ikke solgt.","Forestil dig et helt almindeligt kanban-board med kolonner fra Backlog til Færdig, bortset fra at kortene bliver taget op af AI-agenter. De melder fremskridt, spørger, når de sidder fast, og venter altid på din tommelfinger op."]},{"n":55,"texts":["AI-gile er et kanban-board, hvor teamet består af AI-agenter. Hvert projekt har en lead, der planlægger arbejdet, og hjælpere, der bygger det. Når en funktion er klar, prøver en AI-tester den og tager et skærmbillede, og så lander den i din bunke. Godkend den, eller skriv en kommentar, så laver de den om.","Det startede som én persons måde at holde styr på mange AI-kodesessioner på én gang og voksede til et rigtigt board. Det kører på din maskine, kræver ingen konto og har ingen trackere. Det er gratis for venner og nysgerrige. Det er også ufærdigt, så regn med ru kanter og en overraskelse nu og da.","Her er den ærlige version. Du skal stadig selv have idéerne, og du skal stadig selv tjekke resultaterne. AI-gile klarer alt derimellem: det holder kortene i orden, vækker den rigtige agent, når du skriver en kommentar, viser præcis, hvad der er ændret, og samler det hele i én kort bunke til dig."]},{"n":89,"texts":["AI-gile er et gratis kanban-board, som du kører på din egen computer. I stedet for mennesker har hvert projekt et team af AI-agenter: en lead, der gør dine idéer til kort og en plan, og hjælpere, der tager kortene op i prioriteret rækkefølge. Når noget er bygget, følger en AI-tester testtrinene og viser dig, hvad den så. Derefter venter det i én bunke, der hedder Til dig. Du godkender det, eller du skriver en kommentar, og teamet prøver igen. Intet når nogensinde til Færdig uden dig.","Nogle ting, du måske ikke venter. En nattevagt holder To do-kolonnen fyldt op, mens du sover, og vælger kort, der ikke kræver svar fra dig. En token-tæller viser, hvor meget agenterne har brugt i dag og i denne uge, og No Token Mode siger til dem, at de skal holde op med at bruge. Du kan skrive til venner, og private beskeder er end-to-end-krypterede. Boardet taler omkring 120 sprog, blandt andet hollandsk, flamsk, pirat og klingon. Intet af det koster en krone, og ingen prøver at sælge dig det.","AI-gile er et lille, personligt projekt, ikke en virksomhed. Rich ville passe flere AI-kodeprojekter uden at åbne hver eneste app for at tjekke dem, så han og agenterne byggede et board til det og brugte derefter boardet til at bygge resten af sig selv. Det er i lukket pre-alfa, hvilket betyder, at det virker, stort set, for en lille håndfuld venner. Der er ingen prisside, intet nyhedsbrev og ingen vækstplan. Lyder det nyttigt, kan du bede om at prøve det, når det åbner lidt mere op."]},{"n":144,"texts":["AI-gile er et kanban-board til ét menneske og en masse AI-agenter. Det kører på din egen computer, og det er helt gratis. Du tilføjer projekter, og hvert projekt får en lead og et lille team. Du chatter med leaden, lidt ligesom på Discord, og beskriver en idé; leaden gør den til kort og en plan og venter så på, at du trykker Go. Teamet arbejder kortene igennem i prioriteret rækkefølge ved hjælp af en enkel kommandolinje, lavet til sprogmodeller. Før noget kommer tilbage til dig, følger en AI-tester trinene i en kopi af appen og vedhæfter et skærmbillede. Færdigt arbejde lander i din bunke med de ændrede filer og forskellen. Du godkender det, eller du skriver en kommentar, og teamet vågner og prøver igen. Kun du kan flytte et kort til Færdig. Der er ingen konti, ingen trackere og ingen cookies, og det hele bliver på din egen computer.","En dag med AI-gile, cirka. Om aftenen skriver du et par kommentarer: denne knap sidder det forkerte sted, den liste burde være sorteret, kunne vi få en mørk tilstand. Du går i seng. Agenterne læser kommentarerne, laver ændringerne, tester dem og afleverer dem tilbage til dig. Hvis To do løber tør, fylder nattevagten den op fra backloggen med kort, der ikke kræver svar fra dig. Om morgenen ligger der én kort bunke: et par spørgsmål og et par ting at prøve, hver med trin, som en søvnig person kan følge, og et skærmbillede af, at det virker. Du klikker dig igennem, godkender de gode og sender resten tilbage. En token-tæller viser, hvad det hele brugte, og No Token Mode er der til de magre uger. Så spiser du morgenmad, som agenterne endnu ikke kan hjælpe med.","Først, hvad AI-gile ikke er. Det er ikke en startup, det er ikke til salg, og ingen indsamler dine data. Det er et gratis board, der kører på din computer, uden konti, uden trackere og uden cookies. Hvad det er: ét ryddeligt sted, hvor du kan se alle dine AI-kodeprojekter på én gang, med et team af agenter, der tager kortene, og dig, der træffer beslutningerne. Det slår beslægtede kort sammen, retter rodede titler og holder øje med, hvor slank koden bliver. Det taler omkring 120 sprog, fra hollandsk og flamsk til pirat og klingon. Venner kan skrive til hinanden, privat og krypteret. Det er bygget af Rich og et stort antal tålmodige agenter, mest ved at bruge sig selv. Det er i lukket pre-alfa, så det er groft nogle steder. Lyder det som sjov, så spørg pænt, og måske kommer du tidligt med."]}],"quips":{"1":"Ét ord. Dristigt. Måske for dristigt.","3":"Tre ord. Allerede mere ærligt end de fleste produktsider.","8":"Otte ord. Stadig kortere end et stand-up.","21":"Længderne er i øvrigt story points. Selvfølgelig er de det.","55":"Femoghalvtreds ord. To kort blev færdige, mens du læste det.","144":"Det var den lange. Der er ingen 233. Agenterne er gået i seng."}},"timeline":{"first-idea.name":"Den første idé","first-idea.line":"Den allerførste samtale, før der fandtes nogen kode.","first-board.name":"Første board","first-board.line":"Et board, der følger sin egen opbygning: kort, kolonner, træk og slip, projekter.","team-roles.name":"Team og roller","team-roles.line":"Agentprofiler, teamskabeloner, rum og hvem der gør hvad.","install.name":"Installation og udgivelser","install.line":"En zip, en ven kan installere, selvopdatering, kanaler og tilbagerulning.","usage-saver.name":"Forbrugsbesparelse","usage-saver.line":"Mål, hvad kørsler koster, hold koden slank, spar på din grænse.","friends.name":"Venner og deling","friends.line":"Private beskeder, et krypteret relæ, invitationer, roller og delte projekter.","languages.name":"Sprog","languages.line":"Hver skærmtekst i en sprogfil, med hollandsk og flamsk først.","ai-tester.name":"AI-tester","ai-tester.line":"En tester tjekker hver aflevering først og viser, hvad den så.","website.name":"Hjemmesiden","website.line":"aigile.lol, teaseren og denne tidslinje.","streaming.name":"Chat og streaming","streaming.line":"Discord, Twitch, OBS, streamertilstand, GIF'er og emojis.","no-ai.name":"Udgaven uden AI","no-ai.line":"Et board til folk, der koder uden AI, og offentlige boards.","night-watch.name":"Nattevagt","night-watch.line":"En vagtmand og en Scrum Master holder teamene på sporet, mens du sover.","p-more.name":"Alt det andet","p-more.line":"Mindre idéer, der stadig venter på deres tur.","p-android.name":"Telefon og Android","p-android.line":"Nå dit board fra en telefon, og så en indbygget Android-app.","p-release.name":"Alfa og videre","p-release.line":"Lukket alfa, den levende hjemmeside, så beta.","p-languages.name":"Flere sprog","p-languages.line":"130 sprog og en fordybelsestilstand for dem, der lærer.","p-engines.name":"Flere AI-motorer","p-engines.line":"Vælg Claude, Codex, Gemini, Copilot eller Cursor for hver agent.","p-pro.name":"Professionel praksis","p-pro.line":"Risikomærker, merge-porte, hændelseskort og autoværn.","p-self.name":"At passe på dig","p-self.line":"Træt-tilstand, påmindelser om selvomsorg og 4:20.","p-servers.name":"Servere og vækst","p-servers.line":"Globale serverindstillinger, roller og planlægning for vækst.","p-livestream.name":"Streaming-ekstra","p-livestream.line":"Twitch-chat, egne emojis og en offentlig live-visning."},"words":{"button":"📖 Fagsprog","h":"📖 Ord forklaret","intro":"Gratis undervisning på almindeligt sprog: hvert ord, du møder, fra en første idé til en tjeneste, folk stoler på, med agilt arbejde, udvikling, sikkerhed og arbejde med AI undervejs.","search":"Søg efter et ord…","none":"Intet ord passer.","close":"Luk","count":{"one":"{count} ord","other":"{count} ord"},"groups":[{"id":"idea","name":"💡 Idé og forundersøgelse"},{"id":"plan","name":"🗺️ Planlægning af arbejdet"},{"id":"agile","name":"🔁 Agile arbejdsmåder"},{"id":"build","name":"🛠️ At bygge det"},{"id":"test","name":"🧪 Test og kvalitet"},{"id":"change","name":"🔀 At ændre det sikkert"},{"id":"run","name":"🛎️ At drive en service"},{"id":"sec","name":"🔒 Sikkerhed og privatliv"},{"id":"ai","name":"🤖 Arbejde med AI"},{"id":"money","name":"💰 Penge og licenser"}],"list":[{"id":"discovery","g":"idea","word":"Forundersøgelse (discovery)","text":"Den tidlige fase, hvor man finder ud af, hvilket problem der er værd at løse og for hvem, før noget bliver bygget.","also":["discovery","forundersøgelsesfase","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problemformulering","text":"Én eller to sætninger om, hvem der har et problem, hvad det er, og hvorfor det betyder noget, så alle sigter mod det samme.","also":["problemformuleringer","problem statement"]},{"id":"user","g":"idea","word":"Bruger","text":"En person, der bruger det, du bygger. Det er deres behov, arbejdet er til for.","also":["brugere","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Interessent","text":"Enhver, der interesserer sig for, hvordan arbejdet ender, eller som bliver berørt af det, for eksempel dem, der betaler for det, bruger det eller supporterer det.","also":["interessenter","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"En opdigtet, men realistisk person, der står for én slags bruger, så teamet kan spørge: ”Ville Sam synes, det her er nemt?”","also":["personaer","personas"]},{"id":"userresearch","g":"idea","word":"Brugerundersøgelse","text":"At tale med og observere rigtige mennesker for at finde ud af, hvad de har brug for, i stedet for at gætte.","also":["brugerinterviews","user research","user interviews"]},{"id":"journey","g":"idea","word":"Brugerrejse","text":"De skridt, en person tager for at få noget gjort, fra første gang man hører om det, til man er færdig, også uden for dit produkt. Når du tegner den op, kan du se, hvor folk går i stå.","also":["brugerrejser","kunderejse","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Smertepunkt","text":"Noget, der irriterer eller forsinker folk i dag. Gode produkter fjerner smertepunkter.","also":["smertepunkter","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Antagelse","text":"Noget, du tror, men endnu ikke har tjekket. Når du skriver antagelser ned, kan du se, hvad der skal testes først.","also":["antagelser","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypotese","text":"Dit bedste bud, som du vil afprøve, med hvad du forventer, der vil ske, for eksempel ”folk tilmelder sig, hvis den første måned er gratis”.","also":["hypoteser","hypothesis"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"En lille planlagt test for at se, om en idé virker, før du satser meget på den.","also":["eksperimenter"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Et hurtigt, groft forsøg på at se, om en idé overhovedet kan lade sig gøre. Det bliver som regel smidt væk, når du har fået svaret.","also":["PoC","proof of concept","konceptbevis"]},{"id":"prototype","g":"idea","word":"Prototype","text":"En tidlig model af produktet, ofte billeder, man kan klikke i, så idéen kan prøves af på folk, før den bygges ordentligt.","also":["prototyper","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (skitse af en side)","text":"En enkel skitse af en skærm, der viser, hvor tingene skal sidde, uden farver eller rigtigt indhold.","also":["wireframes","skitse"]},{"id":"mockup","g":"idea","word":"Mockup (visuel model)","text":"Et detaljeret billede af, hvordan en skærm kommer til at se ud, med rigtige farver og tekster, men hvor intet virker endnu.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Businesscase","text":"Begrundelserne for at lave et projekt: hvad det koster, hvad det indbringer eller sparer, og hvad risiciene er.","also":["businesscases","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Gennemførlighed","text":"Om noget virkelig kan bygges og vedligeholdes med den tid, de penge og de kompetencer, du har.","also":["gennemførlig","feasibility"]},{"id":"outcome","g":"idea","word":"Effekt (outcome)","text":"Den forandring, du ønsker for folk, for eksempel færre glemte aftaler. Den er vigtigere end hvor meget du bygger.","also":["effekter","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Leverance (output)","text":"Noget, teamet laver, for eksempel en ny skærm eller en rapport. At det bliver lavet, betyder ikke automatisk, at det hjælper nogen.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Succesmål","text":"Et tal, der viser, om arbejdet gjorde det, det var til for, for eksempel at flere gennemfører deres bestilling.","also":["succesmål","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Nøgletal (KPI)","text":"Et vigtigt tal, du følger for at se, om det går godt, for eksempel tilmeldinger pr. uge.","also":["KPI","KPI'er","KPIs","nøgletal","key performance indicator"]},{"id":"okr","g":"idea","word":"Mål og nøgleresultater (OKR)","text":"En måde at sætte mål på: målet siger, hvad du vil, og nogle få nøgleresultater er de tal, der viser, at du er nået i mål.","also":["OKR","OKR'er","OKRs"]},{"id":"product","g":"plan","word":"Produkt","text":"Det, der bliver bygget og vedligeholdt til brugerne, for eksempel en app, et websted eller et værktøj.","also":["produkter","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Produktvision","text":"En kort erklæring om, hvem produktet hjælper, og hvor det er på vej hen på lang sigt.","also":["visionserklæring","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"Personen, der bestemmer, hvad der bygges og i hvilken rækkefølge, så teamet altid arbejder på det vigtigste. I AI-gile er det dig.","also":["PO","produktejer","product owner","product owners"]},{"id":"pm","g":"plan","word":"Produktchef (PM)","text":"Personen, der tager sig af et produkts retning: hvilke problemer det løser, for hvem og hvorfor. PM kan også betyde projektleder, så tjek, hvad der menes.","also":["produktchefer","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Projektleder","text":"Personen, der sørger for, at et projekt holder tid og budget, og holder styr på, hvem der gør hvad og inden hvornår.","also":["projektledere","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Køreplan (roadmap)","text":"En grov plan for, hvad der kommer de næste måneder, i rækkefølge. Den viser retning, ikke præcise datoer, og ændrer sig, efterhånden som du lærer mere.","also":["køreplaner","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Milepæl","text":"Et punkt i et projekt, der er værd at markere, som ”første version er live” eller ”100 brugere”.","also":["milepæle","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Den mindste version af et produkt, der stadig er til nytte for rigtige mennesker, så du kan lære af dem tidligt.","also":["MVP","MVP'er","MVPs","minimum viable product","mindste brugbare produkt"]},{"id":"requirement","g":"plan","word":"Krav","text":"Noget, det færdige produkt skal kunne eller være.","also":["krav","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Omfang (scope)","text":"Hvad der er med i arbejdet og, lige så vigtigt, hvad der ikke er.","also":["scope","inden for scope","uden for scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep (snigende udvidelse)","text":"Når der hele tiden lægges mere til arbejdet lidt ad gangen, uden at nogen er blevet enige om ekstra tid eller omkostninger, så det aldrig helt bliver færdigt.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Funktion","text":"Én ting, produktet kan gøre for folk, for eksempel ”nulstil din adgangskode”.","also":["funktioner","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic (stor arbejdspakke)","text":"Et stort stykke arbejde, der er for stort til én omgang, så det deles op i mindre kort.","also":["epics","epic"]},{"id":"story","g":"plan","word":"Brugerhistorie (user story)","text":"Et lille stykke arbejde skrevet fra brugerens side: ”Som kunde vil jeg gemme min indkøbskurv, så jeg kan afslutte købet senere.” Den starter en samtale om, hvad der skal bygges.","also":["brugerhistorier","user story","user stories"]},{"id":"ac","g":"plan","word":"Acceptkriterier (AC)","text":"De tjek, et kort skal bestå for at tælle som færdigt, aftalt før arbejdet begynder, for eksempel ”kurven er der stadig, når jeg logger ud og ind igen”.","also":["AC","acceptkriterium","acceptance criteria"]},{"id":"task","g":"plan","word":"Opgave","text":"Et enkelt stykke arbejde, der skal gøres, ofte et lille skridt i en større historie.","also":["opgaver","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Sag (ticket)","text":"Et andet ord for et kort: ét stykke arbejde eller én henvendelse, der følges fra start til slut.","also":["sager","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritet","text":"Hvor vigtigt eller hastende noget er i forhold til alt andet, så det vigtigste arbejde kommer først.","also":["prioriteter","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritering","text":"At sætte arbejde i rækkefølge efter vigtighed. En almindelig metode er MoSCoW: Must have (skal), Should have (bør), Could have (kan), Won’t have (ikke denne gang).","also":["prioritere","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimat","text":"Et bedste bud på, hvor stort et stykke arbejde er, eller hvor lang tid det tager. Det er et gæt, ikke et løfte.","also":["estimater","skøn","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"En måde at gætte på størrelsen af arbejde ved at sammenligne kort med hinanden (”cirka dobbelt så stort som det der”) i stedet for i timer. De er ikke til at sammenligne teams med.","also":["storypoint","story point","point"]},{"id":"tshirt","g":"plan","word":"T-shirtstørrelser","text":"At gætte på størrelsen af arbejde som S, M, L eller XL. Hurtigt og godt nok til tidlig planlægning.","also":["t-shirt sizing","t-shirt sizes","t-shirtstørrelse"]},{"id":"poker","g":"plan","word":"Planlægningspoker","text":"Et spil til at estimere: alle viser et størrelseskort på samme tid, og så forklarer dem med det højeste og det laveste bud hvorfor.","also":["Scrum-poker","planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"Afhængighed","text":"Når ét stykke arbejde ikke kan begynde eller blive færdigt, før et andet er det.","also":["afhængigheder","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Hindring (blocker)","text":"Alt, der forhindrer arbejdet i at komme videre lige nu, som et svar, der mangler, eller et værktøj, der er gået i stykker.","also":["hindringer","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"Datoen, hvor noget senest skal være færdigt.","also":["deadlines","frist","sidste frist"],"noTip":1},{"id":"deliverable","g":"plan","word":"Leverance (deliverable)","text":"Noget konkret, som arbejdet frembringer og afleverer, for eksempel en fungerende side eller en rapport.","also":["leverancer","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prognose","text":"En forudsigelse af, hvad der sandsynligvis sker, for eksempel hvornår arbejdet er færdigt, ud fra det du ved indtil nu.","also":["prognoser","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Måltal","text":"Alt, du måler og følger over tid, for eksempel sidebesøg eller hvor lang tid det tager at rette en fejl.","also":["måltal","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Det, folk fortæller dig om dit arbejde, både godt og dårligt. At få det tidligt og ofte er kernen i agilt arbejde.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ventelisten med idéer og arbejde, der endnu ikke er planlagt, med det vigtigste øverst. Der bliver ikke arbejdet på noget af det, før det flyttes til To do."},{"id":"sprint","g":"agile","word":"Sprint","text":"En kort, fast arbejdsperiode (ofte en eller to uger, aldrig mere end en måned) med et mål og et aftalt sæt kort, der skal blive færdige.","also":["sprints","sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Et hurtigt dagligt tjek: hvad hvert teammedlem har lavet, hvad de gør nu, og hvad der står i vejen. I Scrum hedder det den daglige scrum.","also":["standup","stand-ups","daglig scrum","daglig stand-up","daily scrum","daily stand-up","morgenmøde"]},{"id":"kanban","g":"agile","word":"Kanban","text":"En arbejdsmåde, hvor kort flytter sig hen over et boards kolonner (som To do, I gang, Færdig), og teamet begrænser, hvor meget der er i gang på én gang, så arbejdet bliver ved med at flyde."},{"id":"wip","g":"agile","word":"WIP-grænse","text":"WIP er kort for work in progress, igangværende arbejde. En WIP-grænse er det højeste antal kort, en kolonne bør rumme på én gang, så teamet gør ting færdige, før det starter flere.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Teamets korte tjekliste over, hvad “færdig” betyder, fx testet og forklaret, før et kort bliver givet til dig. Dens tvilling, Definition of Ready, siger, hvornår et kort er klart nok til at gå i gang.","also":["Definition of Ready","DoD","DoR","definition af færdig","Definition of Done"]},{"id":"retro","g":"agile","word":"Retro","text":"Et regelmæssigt tilbageblik på, hvordan teamet arbejder, for at blive enige om en eller to ting, der kan gøres bedre næste gang. Kort for retrospektiv. I AI-gile foreslår en retro en ændring af teamets arbejdsmåder, og du siger Go eller Ikke endnu.","also":["retroer","retrospektiv","retrospective"]},{"id":"swarm","g":"agile","word":"Sværm","text":"Alle mand på dækket: mange dropper andet arbejde for sammen at rette én hastende ting, til den er løst. I AI-gile hjælper alle teams til på ét projekt, og andre projekter må vente imens.","also":["swarm","swarming","sværme"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"I Scrum den person, der hjælper teamet med at arbejde godt: rydder det, der blokerer dem, holder møder på sporet og coacher gode vaner, uden at bestemme over nogen. I AI-gile opdager Lead Scrum Master kort, der sidder fast, skubber til teamene og minder dig om det, der venter, på tværs af alle projekter.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agil","text":"En måde at arbejde på i små skridt: byg lidt, vis rigtige resultater ofte, lær af, hvad folk siger, og ret planen til undervejs, i stedet for at planlægge alt på forhånd.","also":["agilt","agil udvikling","Agile","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Det agile manifest","text":"En kort erklæring skrevet i 2001 af folk, der laver software. Den sætter mennesker, fungerende resultater, tæt samarbejde med kunder og evnen til at reagere på forandringer over tunge planer og papirarbejde.","also":["Agile Manifesto","Manifesto for Agile Software Development","agile manifest"]},{"id":"waterfall","g":"agile","word":"Vandfaldsmodellen","text":"Den ældre arbejdsmåde: planlæg alt, byg så alt, test så alt, ét trin ad gangen. Sene ændringer er svære og dyre.","also":["vandfald","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Én omgang, hvor man bygger noget, tjekker det og forbedrer det. Agilt arbejde er en kæde af dem, og en sprint er en slags iteration.","also":["iterationer","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Et nyt fungerende stykke, der lægges til produktet i en sprint eller arbejdsomgang, og som passer sammen med det, der allerede var der.","also":["inkrementer","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"En populær agil arbejdsmåde: et lille team arbejder i korte sprints mod et mål, med faste roller og nogle få tilbagevendende møder til at planlægge, tjekke og forbedre."},{"id":"scrumteam","g":"agile","word":"Scrumteam","text":"Den lille gruppe, der udfører arbejdet i Scrum: en product owner, en Scrum Master og udviklerne.","also":["Scrum-team","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum-events","text":"De tilbagevendende møder i Scrum: sprintplanlægning, den daglige scrum, sprintreview og retro. Mange kalder dem ceremonier.","also":["ceremonier","Scrum-ceremonier","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprintplanlægning","text":"Mødet i starten af en sprint, hvor teamet bliver enigt om, hvorfor sprinten er vigtig, hvilke kort de tager fat på, og hvordan de begynder.","also":["planlægningsmøde","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprintmål","text":"Én sætning om, hvad en sprint er til for. Små opgaver kan ændre sig undervejs, bare målet nås.","also":["sprintmål","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"De kort, der er valgt til den aktuelle sprint, med teamets plan for at udføre dem.","also":["sprintbacklog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Hele den ordnede liste over alt, der måske skal bygges til produktet, med det vigtigste øverst. Den ændrer sig hele tiden, efterhånden som du lærer mere.","also":["produktbacklog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Produktmål","text":"Det større resultat, produktet arbejder hen imod, og som hjælper teamet med at vælge, hvad der skal gøres næste gang.","also":["produktmål","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Backlog-forfining (refinement)","text":"Regelmæssigt at gennemgå backloggen for at rydde op, dele, ordne og uddybe kort, så de er klar til at blive taget. Kaldes også backlog grooming.","also":["backlog grooming","refinement","forfining","backlog-grooming"]},{"id":"sprintreview","g":"agile","word":"Sprintreview","text":"Et møde i slutningen af en sprint, hvor teamet viser, hvad det blev færdigt med, og hører, hvad folk synes, for at bestemme, hvad der kommer næste gang.","also":["sprintreviews","sprint review","sprint reviews","sprintdemo"]},{"id":"demo","g":"agile","word":"Demo","text":"At vise færdigt arbejde, der virker, live, for dem, der har bestilt det.","also":["demoer","demos","demonstration"],"noTip":1},{"id":"timebox","g":"agile","word":"Tidsramme (timebox)","text":"En fast afsat tid til noget. Når den er gået, stopper man, selv om ikke alt er færdigt.","also":["tidsrammer","timeboxed","timeboxes","timebox"]},{"id":"velocity","g":"agile","word":"Velocity (hastighed)","text":"Hvor meget arbejde et team plejer at blive færdigt med i en sprint. Det bruges til at planlægge, hvor meget teamet tager på sig næste gang. Det er ikke en måling af, hvor hårdt folk arbejder.","also":["teamets velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapacitet","text":"Hvor meget arbejde teamet kan tage på sig i en periode, efter ferie og andre opgaver.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-diagram","text":"Et diagram over det arbejde, der er tilbage i en sprint, og som falder dag for dag. Hvis linjen bliver ved med at være flad, sidder noget fast.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Burnup-diagram","text":"Et diagram over færdigt arbejde, der vokser over tid, ved siden af den samlede plan, så du kan se, hvornår du er i mål.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Kanbanboard","text":"Selve boardet: en kolonne for hvert trin i arbejdet, med kort, der flytter sig hen over.","also":["kanbanboards","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull-system (trækkende system)","text":"En arbejdsmåde, hvor nyt arbejde først begynder, når nogen har plads til at tage det, i stedet for at blive skubbet over på nogen, der allerede har fuldt op at lave.","also":["pull","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Hvor gnidningsfrit arbejdet bevæger sig hen over boardet. Godt flow betyder, at kortene hele tiden flytter sig i stedet for at hobe sig op.","also":["arbejdsflow","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Gennemløbstid (lead time)","text":"Hvor lang tid der går fra, at nogen beder om noget, til det er færdigt.","also":["gennemløbstider","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Cyklustid (cycle time)","text":"Hvor lang tid et kort tager fra det tidspunkt, hvor arbejdet for alvor går i gang på det, til det er færdigt.","also":["cyklustider","cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Gennemstrømning","text":"Hvor mange kort der bliver færdige på en uge eller i en anden fast periode.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Flaskehals","text":"Det ene trin, hvor arbejdet hober sig op og bremser alt, der kommer efter, som den smalle hals på en flaske.","also":["flaskehalse","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Svømmebane (swimlane)","text":"En række på tværs af boardet, der samler kort af én slags, for eksempel hastende arbejde eller ét teams kort.","also":["svømmebaner","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"En arbejdsmåde, der skærer spild væk (alt, der ikke hjælper kunden) og holder arbejdet flydende."},{"id":"waste","g":"agile","word":"Spild","text":"I Lean: alt, der kræver kræfter, men ikke hjælper kunden, som ventetid, omarbejde eller at bygge ting, ingen bruger.","noTip":1},{"id":"kaizen","g":"agile","word":"Løbende forbedring","text":"At blive en lille smule bedre hele tiden gennem små, regelmæssige ændringer og så tjekke, at de hjalp. Retroer er én måde at gøre det på. Kaldes også kaizen.","also":["kaizen","continuous improvement","kontinuerlig forbedring"]},{"id":"selforg","g":"agile","word":"Selvorganiserende team","text":"Et team, der selv bestemmer, hvordan arbejdet skal gøres, i stedet for at få det at vide trin for trin.","also":["selvorganiserende","selvstyrende team","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Tværfagligt team","text":"Et team, der har alle de færdigheder, det skal bruge for selv at gøre arbejdet færdigt, som design, udvikling og test.","also":["tværfaglig","tværfunktionelt","cross-functional"]},{"id":"spike","g":"agile","word":"Spike (kort undersøgelse)","text":"En kort, tidsbegrænset undersøgelse, der skal besvare et spørgsmål, før man går i gang med det rigtige arbejde.","also":["spikes","spike"]},{"id":"rework","g":"agile","word":"Omarbejde","text":"At gøre arbejde om, fordi det ikke blev rigtigt første gang.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agil i stor skala (SAFe)","text":"Måder at bruge agilt arbejde på tværs af mange teams i en stor organisation. SAFe (Scaled Agile Framework) er et velkendt eksempel.","also":["scaled Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Projektets mappe med kode og dens fulde historik af commits. Den kan ligge på din computer, på GitHub eller begge steder.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"En separat arbejdslinje i koden, så man kan lave ændringer uden at røre hovedversionen.","also":["branches","gren"]},{"id":"commit","g":"build","word":"Commit","text":"Et gemt øjebliksbillede af koden med en kort note om, hvad der er ændret. Du kan altid gå tilbage til et.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At sende dine gemte øjebliksbilleder (commits) fra denne computer til den delte kopi online, for eksempel GitHub, så de er sikkerhedskopieret, og andre kan hente dem."},{"id":"merge","g":"build","word":"Merge","text":"At slå ændringerne fra én branch sammen med en anden, som regel tilbage i hovedversionen."},{"id":"pr","g":"build","word":"Pull request","text":"At bede om, at en branchs ændringer bliver tjekket og slået sammen med hovedversionen. Nogle websteder kalder det en merge request.","also":["PR","PR'er","PRs","pull request","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"At rydde op i koden uden at ændre, hvad den gør: mindre filer, tydeligere navne, mindre gentagelse."},{"id":"bug","g":"build","word":"Bug","text":"Noget, der ikke virker, som det skal.","also":["bugs","fejl"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Et ekstra par øjne: en anden end den, der har lavet arbejdet, tjekker det, før det når dig, så færre fejl slipper igennem. I AI-gile tjekker en anden AI hvert kort.","also":["code review","kodegennemgang"]},{"id":"code","g":"build","word":"Kode","text":"De skrevne instruktioner, der fortæller en computer, hvad den skal gøre. Kaldes også kildekode.","also":["kildekode","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Programmeringssprog","text":"Et sprog til at skrive kode i, for eksempel JavaScript, Python eller Java. Forskellige sprog passer til forskellige opgaver.","also":["programmeringssprog","programming language","programming languages"]},{"id":"developer","g":"build","word":"Udvikler (dev)","text":"Nogen, der skriver og ændrer kode. Kaldes også programmør eller softwareudvikler.","also":["udviklere","developer","developers","programmør","programmører","programmer","programmers","softwareudvikler","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programmer, der kører på computere og telefoner, i modsætning til selve maskinerne (hardwaren).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kort for applikation: et program, folk bruger til at få noget gjort, på en telefon, en computer eller i en browser.","also":["apps","applikation","applikationer","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Webapp","text":"En app, der kører i en browser, så der ikke er noget, der skal installeres.","also":["webapps","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Frontend","text":"Den del af en app, du ser og klikker på: skærmene, knapperne og teksterne, ofte i din browser.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Backend","text":"Den del af en app, der arbejder bag kulisserne, gemmer data og gør arbejdet, når du klikker på noget, for eksempel tjekker din adgangskode.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Fullstack","text":"At arbejde med både frontend og backend.","also":["full stack","full-stack","fullstack"]},{"id":"ui","g":"build","word":"Brugerflade (UI)","text":"Det, en person ser og bruger på skærmen: layout, knapper, menuer og tekst.","also":["UI","brugergrænseflade","user interface"]},{"id":"ux","g":"build","word":"Brugeroplevelse (UX)","text":"Hvordan det føles at bruge noget: nemt, tydeligt og behageligt, eller forvirrende og langsomt.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Tilgængelighed (a11y)","text":"At gøre ting brugbare for alle, også for folk, der ikke kan se godt, ikke kan bruge en mus eller bruger en skærmlæser.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Responsivt design","text":"At få sider til at passe og fungere godt på alle skærmstørrelser, fra en telefon til en stor skærm.","also":["responsiv","responsive design"]},{"id":"designsys","g":"build","word":"Designsystem","text":"Et fælles sæt farver, skrifttyper, knapper og regler, så alle skærme ser ud og opfører sig ens.","also":["designsystemer","design system","design systems"]},{"id":"architecture","g":"build","word":"Arkitektur","text":"Systemets overordnede form: hvad hoveddelene er, og hvordan de taler sammen."},{"id":"database","g":"build","word":"Database (DB)","text":"Et ordnet lager af information, lidt ligesom et meget kraftfuldt regneark, som appen kan læse og ændre.","also":["databaser","database","databases","DB"]},{"id":"schema","g":"build","word":"Databaseskema","text":"Databasens opbygning: hvilke tabeller med information den har, og hvad der hører hjemme i hver.","also":["skema","database schema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kort for structured query language: sproget, der bruges til at bede mange databaser om information eller til at ændre den.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information, som en computer gemmer, for eksempel navne, bestillinger eller indstillinger.","also":["oplysninger","datasæt","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"En computer, der altid er tændt og svarer på forespørgsler fra andre computere, for eksempel ved at sende en webside, når du besøger den.","also":["servere","servers"]},{"id":"client","g":"build","word":"Klient","text":"Den side, der beder om noget, oftest din browser eller app, og som taler med en server. I erhvervslivet betyder det også bare en kunde.","also":["klienter","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kort for application programming interface: en fast menu af forespørgsler, som ét program kan sende til et andet, som at bede en vejrtjeneste om dagens prognose.","also":["API'er","APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (endepunkt)","text":"Ét punkt på et API's menu: en webadresse, som et program kan kalde for at hente eller sende noget.","also":["endepunkt","endepunkter","endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"At koble to systemer sammen, så de virker sammen, for eksempel at din webshop sender ordrer til dit regnskabsprogram.","also":["integrationer","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"En besked, som ét system sender til et andet helt af sig selv i det øjeblik, noget sker, for eksempel ”betaling modtaget”.","also":["webhooks"]},{"id":"library","g":"build","word":"Bibliotek (library)","text":"Færdig kode, som en anden har skrevet, og som du kan genbruge i stedet for selv at skrive den.","also":["biblioteker","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (rammeværk)","text":"En færdig struktur til at bygge en app, som afgør meget af, hvordan koden bliver lagt op, som et husskelet, du udfylder.","also":["frameworks","rammeværk","framework"]},{"id":"sdk","g":"build","word":"Udviklingspakke (SDK)","text":"En værktøjskasse med værktøjer, kode og eksempler til at bygge software til en bestemt platform eller tjeneste.","also":["SDK","SDK'er","SDKs"]},{"id":"softdep","g":"build","word":"Softwareafhængighed","text":"Et bibliotek eller værktøj, din kode har brug for for at virke. At holde dem opdateret er vigtigt for sikkerheden.","also":["softwareafhængigheder","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakke","text":"Et bundt færdig kode, du kan installere og bruge i et projekt.","also":["pakker","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakkehåndtering","text":"Et værktøj, der henter og opdaterer de pakker, din kode er afhængig af. npm er et af de mest almindelige.","also":["pakkehåndtering","pakkehåndterer","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Det mest brugte værktøj til at gemme historikken over kodeændringer, som commits og branches."},{"id":"github","g":"build","word":"GitHub","text":"Et websted, der gemmer Git-repos online, så teams kan dele kode, gennemgå ændringer og følge arbejdet."},{"id":"vcs","g":"build","word":"Versionsstyring","text":"At gemme en fuld historik over hver ændring af filerne, så du kan se, hvem der ændrede hvad, og gå tilbage, hvis det er nødvendigt. Git gør det.","also":["kildekodestyring","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Klone (clone)","text":"At lave din egen fulde kopi af et repo, med historikken, på din computer.","also":["klon","klonet","kloner","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (hent)","text":"At hente de seneste commits fra den delte kopi (for eksempel GitHub) ned på din computer. Det modsatte af push.","also":["git pull","hent"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hovedbranch (main)","text":"Den officielle version af koden, som alle tager udgangspunkt i, ofte kaldet main eller master.","also":["hovedgren","main","master","master branch","main branch"]},{"id":"conflict","g":"build","word":"Flettekonflikt (merge conflict)","text":"Når to ændringer rører ved de samme linjer på forskellig måde, så computeren ikke kan sætte dem sammen, og et menneske må vælge.","also":["mergekonflikt","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (forskelle)","text":"En visning, der viser præcis, hvad der er ændret mellem to versioner: tilføjede linjer og fjernede linjer.","also":["diffs","diff","forskelle"]},{"id":"fork","g":"build","word":"Fork (egen kopi)","text":"Din egen kopi af en andens repo, som du kan ændre uden at påvirke originalen.","also":["forke","forks","forked","fork"]},{"id":"script","g":"build","word":"Script","text":"Et kort program, der klarer én opgave helt selv, for eksempel rydder op i filer eller starter appen.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (byg)","text":"At gøre koden til noget, der er klar til at køre, eller selve det resultat, der er klar til at køre.","also":["byg","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilere","text":"At oversætte kode, som mennesker har skrevet, til en form, computeren kan køre direkte.","also":["kompilator","kompileret","compile","compiler"]},{"id":"cli","g":"build","word":"Kommandolinje (CLI)","text":"Et tekstvindue, hvor du skriver instruktioner til computeren i stedet for at klikke. Kaldes også terminalen.","also":["kommandoprompt","terminal","command line","command-line","CLI"]},{"id":"config","g":"build","word":"Konfiguration (config)","text":"De indstillinger, der styrer, hvordan software opfører sig, gemt adskilt fra koden, så de er nemme at ændre.","also":["config","konfig","configuration","konfiguration"],"noTip":1},{"id":"envvar","g":"build","word":"Miljøvariabel","text":"En indstilling, der gives til et program, når det starter, ofte til adresser eller adgangskoder, så de ikke skrives ind i koden.","also":["miljøvariabler","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Fejlfinding (debugging)","text":"At lede efter, hvorfor noget ikke virker, og rette det.","also":["fejlfinde","debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Parprogrammering","text":"To personer (eller en person og en AI), der arbejder på den samme kode sammen, hvor den ene skriver og den anden tjekker.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Dokumentation (docs)","text":"Skrevne forklaringer på, hvordan noget virker, eller hvordan man bruger det.","also":["docs","dokumentation","documentation"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Den første fil, man skal læse i et repo: hvad projektet er, og hvordan man får det i gang.","also":["READMEs","læs mig"]},{"id":"legacy","g":"build","word":"Ældre system (legacy)","text":"Et ældre system, der stadig bruges, og som er svært at ændre, ofte fordi næsten ingen længere forstår det.","also":["legacy","legacysystem","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Teknisk gæld","text":"Genveje, der sparer tid nu, men gør senere ændringer langsommere, som et lån, der løber op med renter. Refaktorering betaler gælden ned.","also":["teknikgæld","tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Et tjek af, at noget virker, som det skal. Nogle tests kører computeren selv, hver gang koden ændres; andre består i, at du prøver et færdigt kort af, før du godkender det.","also":["tests","teste"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kort for quality assurance, kvalitetssikring: alt, der gøres for at sikre, at arbejdet er rigtigt, før det går live. I AI-gile betyder det de automatiske tjek: når QA er rødt, er noget slået fejl, og det kan ikke gå live, før det er rettet.","also":["kvalitetstjek","kvalitetssikring","quality checks"]},{"id":"testpile","g":"test","word":"Testbunke","text":"De færdige kort, der venter på, at du prøver dem, det ene efter det andet. Godkend et, eller send det tilbage med en note, så kommer det næste frem.","also":["testbunker","test pile"]},{"id":"autotest","g":"test","word":"Automatisk test","text":"Et tjek, computeren selv kører, hver gang koden ændres, for at fange fejl tidligt.","also":["automatiske tests","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manuel test","text":"En person, der prøver arbejdet af i hånden for at se, om det opfører sig, som det skal.","also":["manuelle tests","manuel testning","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Enhedstest (unit test)","text":"Et lille automatisk tjek af ét lille stykke kode for sig.","also":["enhedstests","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Integrationstest","text":"Et tjek af, at flere dele virker godt sammen, ikke kun én ad gangen.","also":["integrationstests","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end-test (E2E)","text":"En test, der opfører sig som en rigtig bruger fra start til slut, for eksempel tilmelder sig, køber og betaler.","also":["E2E","end-to-end test","end-to-end tests","helhedstest"]},{"id":"uat","g":"test","word":"Accepttest (UAT)","text":"De, der har bestilt arbejdet, prøver det selv og siger, om det gør det, de har brug for. Testbunken er AI-giles udgave af det.","also":["UAT","brugeraccepttest","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Noget, der før virkede, men gik i stykker efter en ændring. Regressionstests tjekker, at de gamle ting stadig virker.","also":["regressioner","regressionstest","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Røgtest (smoke test)","text":"Et meget hurtigt tjek af, at det vigtigste overhovedet virker, for eksempel lige efter en ændring er gået live. Hvis den fejler: stop og se efter.","also":["smoke test","smoke tests","smoketest"]},{"id":"exploratory","g":"test","word":"Udforskende test","text":"At prøve produktet frit og pirke til det på forskellige måder for at finde problemer, som planlagte tjek overser.","also":["udforskende testning","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Testcase","text":"Ét nedskrevet scenarie at prøve: trinnene, og hvad der skal ske.","also":["testcases","test case","test cases"]},{"id":"coverage","g":"test","word":"Testdækning","text":"Hvor stor en del af koden der bliver tjekket af automatiske tests. Mere er som regel mere sikkert, men høj dækning alene beviser ikke, at det virker godt.","also":["dækning","kodedækning","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Testdata","text":"Opdigtede eksempeldata, der bruges under test, så ingen rigtig persons private oplysninger bliver blotlagt.","also":["test data","test fixtures","testgrundlag"]},{"id":"edgecase","g":"test","word":"Grænsetilfælde (edge case)","text":"En usædvanlig situation helt ude ved grænsen, som en tom formular eller et navn med apostrof, hvor tingene ofte går i stykker.","also":["grænsetilfælde","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Happy path (når alt går godt)","text":"Den normale rute, hvor alt går rigtigt. Gode tests prøver også de veje, hvor noget går galt."},{"id":"perftest","g":"test","word":"Ydelsestest","text":"At tjekke, hvor hurtigt noget er, og hvor godt det klarer pres.","also":["ydelsestestning","performancetest","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Belastningstest","text":"At tjekke, hvordan et system klarer, at mange bruger det på én gang.","also":["belastningstestning","loadtest","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Sikkerhedstest","text":"At lede efter svagheder, der kan lade nogen misbruge et system eller se det, de ikke bør.","also":["sikkerhedstestning","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Tilgængelighedstest","text":"At tjekke, at folk med forskellige forudsætninger kan bruge produktet, også med skærmlæser eller kun et tastatur.","also":["tilgængelighedstestning","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting (kodetjek med værktøj)","text":"Et automatisk tjek, der finder sandsynlige fejl og sjusket stil i kode, som en stavekontrol til programmer.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Statisk analyse","text":"At lede efter problemer i koden ved at læse den automatisk, uden at køre den.","also":["statisk kodeanalyse","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Upålidelig test (flaky)","text":"En test, der somme tider består og somme tider fejler uden nogen tydelig grund, så den ikke kan stoles helt på.","also":["flaky test","flaky tests","ustabil test"]},{"id":"repro","g":"test","word":"Genskab fejlen (repro)","text":"At få en fejl til at opstå igen med vilje ved at følge de samme trin, så den kan studeres og rettes. At skrive de trin ned er den mest nyttige del af en fejlrapport.","also":["repro","reproducere","trin til at genskabe","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Alvorlighed","text":"Hvor slemt et problems virkning er, fra en lille irritation til, at alt står stille.","also":["alvorlighedsgrad","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"At kopiere en ny version af softwaren over på de computere, der kører den, for eksempel en testkopi eller den rigtige tjeneste."},{"id":"release","g":"change","word":"Udgivelse","text":"En navngivet pakke færdigt arbejde, der går live samlet, med korte noter om, hvad der er ændret. 🚀 Udgivelser skriver noterne ud fra de færdige kort.","also":["udgivelser","release","releases"]},{"id":"rollback","g":"change","word":"Rul tilbage","text":"At gå tilbage til den seneste version, der virkede, når en ny giver problemer. I AI-gile samler Rul tilbage fortryd-trinnene, der er skrevet til hver ændring, i én tjekliste.","also":["rollback","tilbagerulning","rullet tilbage"]},{"id":"live","g":"change","word":"Live","text":"Den rigtige version, som folk bruger, i modsætning til en kopi til at prøve ting af på. Udviklere kalder den også produktion.","also":["produktion","production"],"noTip":1},{"id":"change","g":"change","word":"Ændring","text":"En planlagt ændring af noget, folk er afhængige af, skrevet ned først: hvad, hvorfor, risikoen, hvornår og hvordan den fortrydes. Start en med 🔀 Anmod om en ændring.","also":["ændringer","ændringsanmodning","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Noget, der kan gå galt, scoret efter hvor sandsynligt og hvor slemt det ville være. ⚠️ Risici samler dem i én liste, højeste score først, hver med en dato for at kigge på den igen.","also":["risici","risikoregister"]},{"id":"chgwin","g":"change","word":"Ændringsvindue","text":"De tidspunkter, hvor ændringer må gå live, fx en stille tirsdag aften. Uden for et vindue kan et ændringskort ikke gøres færdigt, medmindre det er en nødsituation.","also":["ændringsvinduer","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Et sidste tjek lige før en ændring går live: hver, der skal godkende, siger Go eller No go. Det går kun videre, når alle siger Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Godkendelse","text":"At vente på et ja, før arbejdet starter. Et kort, som en ven opretter, eller en ændring venter i ✅ Godkendelser, indtil du godkender eller afviser det.","also":["godkendelser","approval"]},{"id":"quiettime","g":"change","word":"Stille periode","text":"Et tidsrum, for eksempel under en livestream, en demo eller natten over, hvor intet går live. Teamene arbejder og tester videre, men at gå live venter, til det er slut. Andre steder kaldes det et ændringsstop (change freeze).","also":["stille perioder","ændringsstop","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"En arbejdsmåde, hvor dem, der bygger software, og dem, der driver den, arbejder som ét team, med meget automatisering, så ændringer går live ofte og sikkert."},{"id":"cicd","g":"change","word":"CI/CD (kontinuerlig integration og levering)","text":"Alles ændringer bliver ofte slået sammen med hovedversionen og tjekket automatisk hver gang (kontinuerlig integration), så softwaren altid er klar til at gå live med et tryk på en knap (kontinuerlig levering).","also":["CI/CD","CI","CD","kontinuerlig integration","kontinuerlig levering","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Kontinuerlig udrulning","text":"Et skridt videre end kontinuerlig levering: hver ændring, der består tjekkene, går live af sig selv, uden en knap at trykke på.","also":["continuous deployment","continuous deployments","kontinuerlig deployment"]},{"id":"pipeline","g":"change","word":"Pipeline (byggekæde)","text":"Den automatiske række af trin, en ændring går igennem på vej til live, som build, test og så udrulning.","also":["pipeline","pipelines","byggekæde"]},{"id":"environment","g":"change","word":"Miljø","text":"Én adskilt kopi af systemet til ét formål, for eksempel én at bygge i, én at teste i og den rigtige, der er live.","also":["miljøer","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Udviklingsmiljø","text":"Den kopi, en udvikler arbejder i, ofte på sin egen computer, hvor det ikke skader nogen, hvis noget går i stykker.","also":["dev-miljø","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Testmiljø","text":"En adskilt kopi af systemet, der kun bruges til test, så den rigtige tjeneste ikke bliver rørt.","also":["testmiljøer","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging (forproduktion)","text":"En sidste kopi, der er sat op præcis som live-miljøet, til et sidste tjek, før en ændring går live.","also":["forproduktion","staging","staging environment"]},{"id":"artifact","g":"change","word":"Build-artefakt","text":"Den fil eller pakke, et build giver, klar til at blive gemt, tjekket eller sat live.","also":["build-artefakter","artefakt","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix (hurtig rettelse)","text":"En hastende rettelse, der sendes hurtigt live, uden for den normale plan, fordi noget vigtigt er gået i stykker.","also":["hotfix","hotfixes","akutrettelse"]},{"id":"patch","g":"change","word":"Patch (rettelse)","text":"En lille opdatering, der retter en fejl eller lukker et sikkerhedshul. Det er vigtigt at installere sikkerhedspatches hurtigt.","also":["patches","sikkerhedspatch","patch","security patch","security patches"]},{"id":"version","g":"change","word":"Versionsnummer","text":"En betegnelse som 2.4.1, der fortæller, hvilken udgave du har. Ofte ændrer det første tal sig ved store ændringer og det sidste ved små rettelser.","also":["versionsnumre","semantisk versionering","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Udgivelsesnoter","text":"En kort, enkel liste over, hvad der er ændret i en udgivelse, til dem, der bruger den, med rettelser og kendte begrænsninger. Kaldes også en ændringslog.","also":["ændringslog","release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Funktionsflag (feature flag)","text":"En tænd/sluk-knap til en funktion, så nyt arbejde kan gå live skjult og blive tændt (eller slukket igen) uden en ny udgivelse.","also":["feature flag","feature flags","feature toggle","feature toggles","funktionskontakt"]},{"id":"rollfwd","g":"change","word":"Ret fremad (roll forward)","text":"At rette en dårlig udgivelse ved hurtigt at sende en ny, rettet version ud i stedet for at gå tilbage til den gamle.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Kanariefuglsudrulning (canary release)","text":"At sætte en ændring live for en lille gruppe først og kun for alle, når det ser fint ud. Opkaldt efter de kanariefugle, minearbejdere tog med under jorden som tidlig advarsel.","also":["canary release","canary releases","canary","kanariefugl"]},{"id":"bluegreen","g":"change","word":"Blå-grøn udrulning (blue-green)","text":"At have to kopier af live-systemet og flytte folk over til den nye på én gang, så man med det samme kan skifte tilbage, hvis det går galt.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Udrulning uden nedetid","text":"At sætte en ny version live, uden at tjenesten nogensinde stopper for brugerne.","also":["zero downtime","zero-downtime","zero-downtime deployment","uden driftsstop"]},{"id":"chgenable","g":"change","word":"Ændringshåndtering","text":"At hjælpe ændringer med at lykkes: veje risikoen, få den rette godkendelse og vælge et godt tidspunkt. Kaldes også change management.","also":["change enablement","change management","forandringsledelse"]},{"id":"cab","g":"change","word":"Ændringsråd (CAB)","text":"En gruppe, der kigger på vigtige ændringer og afgør, om og hvornår de må gennemføres.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standardændring","text":"En ændring med lav risiko, der gøres på den samme gennemprøvede måde hver gang, så den er godkendt på forhånd.","also":["standardændringer","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Normal ændring","text":"En ændring, der skal tjekkes og godkendes, før den må gennemføres.","also":["normale ændringer","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Akut ændring","text":"En ændring, der skal ske med det samme for at rette eller forhindre alvorlige problemer, med en hurtigere godkendelse, der passer til.","also":["akutte ændringer","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatisering","text":"At lade computeren udføre en gentaget opgave selv, så det går hurtigere og bliver gjort på samme måde hver gang.","also":["automatiseret","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktur","text":"De maskiner, netværk og tjenester, softwaren kører på.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruktur som kode (IaC)","text":"At beskrive dine servere og indstillinger i filer, der gemmes sammen med koden, så de kan bygges op på præcis samme måde hver gang.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Skyen","text":"At leje computere, lager og tjenester af en stor udbyder over internettet i stedet for selv at eje maskinerne.","also":["sky","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Skyudbyder","text":"Et firma, der udlejer computerkraft over internettet, for eksempel Amazon Web Services (AWS), Microsoft Azure eller Google Cloud.","also":["skyudbydere","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (webhotel)","text":"Stedet, hvor din app eller dit websted bor og kører, så folk kan nå det, som regel lejet hos et firma.","also":["webhotel","hosting","drift"]},{"id":"domain","g":"change","word":"Domænenavn","text":"Den webadresse, folk skriver ind, som eksempel.dk. Du lejer den for et år ad gangen, så den skal fornyes.","also":["domæne","domænenavne","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Kort for domain name system: internettets telefonbog, som gør et navn som eksempel.dk om til adressen på den rigtige computer.","also":["domain name system","domænenavnesystemet"]},{"id":"container","g":"change","word":"Container","text":"En forseglet pakke med en app og alt, den har brug for, så den kører ens på enhver computer. Docker er det mest kendte værktøj.","also":["containere","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuel maskine (VM)","text":"En simuleret computer, der kører inde i en rigtig, så én stor maskine kan opføre sig som mange.","also":["VM","VM'er","VMs","virtual machines","virtuelle maskiner"]},{"id":"serverless","g":"change","word":"Serverless (serverløs)","text":"At køre kode uden selv at passe nogen servere: udbyderen kører den, når der er brug for det, og du betaler for det, du bruger."},{"id":"lb","g":"change","word":"Load balancer (belastningsfordeler)","text":"Noget, der fordeler besøgende over flere servere, så ingen enkelt bliver overbelastet.","also":["belastningsfordeler","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache (mellemlager)","text":"Et praktisk lager af nylige resultater, der ligger tæt på, så det samme ikke skal hentes eller regnes ud igen. At tømme det kan rette sider, der ser forældede ud.","also":["cache","mellemlager","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Indholdsleveringsnetværk (CDN)","text":"Et verdensomspændende sæt servere med kopier af dine sider og billeder tæt på dine besøgende, så de indlæses hurtigt.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrering","text":"At flytte data eller systemer fra en gammel løsning til en ny, eller forsigtigt ændre, hvordan en database er opbygget.","also":["migreringer","migration","migrations","database migration","databasemigrering"]},{"id":"service","g":"run","word":"Service","text":"Noget, du har bygget, som folk er afhængige af, fx en hjemmeside eller en app, der bliver passet, så den bliver ved med at virke. Sæt flueben i “Dette projekt er en service”, og skriv, hvad den tilbyder, hvem der bruger den, og hvem der har vagten.","also":["services","tjeneste"]},{"id":"uptimepct","g":"run","word":"Oppetid (uptime)","text":"Hvor stor en del af tiden en tjeneste virker, som regel som en procentdel. 99,9 % tillader stadig omkring 43 minutters nedetid om måneden.","also":["uptime","oppetid","oppetidsprocent","uptime percentage"]},{"id":"uptime","g":"run","word":"Oppetidstjek","text":"Et automatisk tjek, hvert par minutter, af at din service stadig svarer. Hvis det fejler flere gange i træk, åbner AI-gile selv et hændelseskort.","also":["oppetidstjek","uptime-tjek","uptime checks"]},{"id":"statuspage","g":"run","word":"Statusside","text":"En offentlig side, der viser, om en service virker (grøn, orange eller rød), med den seneste opdatering, så dem, der bruger den, kan tjekke i stedet for at spørge.","also":["statussider","status page"]},{"id":"desk","g":"run","word":"Servicedesk","text":"Hvor spørgsmål og henvendelser fra dem, der bruger din service, kommer ind. AI-gile sorterer hver enkelt som en anmodning, en hændelse eller en idé, og siger til, når den ligner noget, der allerede er meldt.","also":["servicedesks","helpdesk","support"]},{"id":"svcrequest","g":"run","word":"Serviceanmodning","text":"Nogen, der beder om noget almindeligt, fx en ny konto eller lidt hjælp, i stedet for at melde, at noget er i stykker. Den venter på sin tur; en hændelse går først.","also":["serviceanmodninger"]},{"id":"incident","g":"run","word":"Hændelse","text":"Noget, der er i stykker eller ikke virker ordentligt for dem, der bruger det lige nu, som at webstedet er nede eller meget langsomt. Et 🔥-hændelseskort springer køen over: at få det til at virke igen kommer først.","also":["hændelser","incident","incidents"]},{"id":"major","g":"run","word":"Større hændelse","text":"En stor hændelse: mange berørte, eller penge eller data i fare. Én knap sætter alle teams på den (sværm), vækker den, der har vagten, og beder om en statusopdatering hvert 30. minut.","also":["større hændelser","major incident"]},{"id":"oncall","g":"run","word":"Vagt","text":"At være den, der svarer, når noget går i stykker, også om natten. Hver service har et teammedlem på vagt, som bliver vækket først ved dens hændelser.","also":["på vagt","tilkaldevagt","on call","on-call"]},{"id":"replyby","g":"run","word":"Svarfrist","text":"Hvor længe et kort må vente på et første svar, fx en time for en hændelse. Derefter får det et rødt ur, så intet bliver glemt i stilhed. Kaldes også et responsmål.","also":["svarfrister","responsmål","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Et kort tilbageblik efter en hændelse: hvad skete der, hvad hjalp, og hvad skal ændres, uden at give nogen skylden. En hændelse kan ikke lukkes uden.","also":["post-mortems","postmortem","gennemgang efter hændelse"]},{"id":"problem","g":"run","word":"Problem","text":"Den skjulte årsag bag en eller flere hændelser. Et 🧩 problemkort samler hændelser, der bliver ved med at komme igen, så årsagen bliver fundet og rettet for altid.","also":["problemer"],"noTip":1},{"id":"rootcause","g":"run","word":"Grundårsag","text":"Den egentlige grund til, at noget gik i stykker, ikke bare det, du så gå galt. Ret grundårsagen, og hændelsen holder op med at komme igen.","also":["grundårsager","root cause"]},{"id":"workaround","g":"run","word":"Midlertidig løsning","text":"En måde at holde tingene kørende på, indtil den rigtige rettelse er klar, fx at genstarte noget, når det hænger. Den skrives på problemkortet, så ingen skal finde ud af det igen.","also":["midlertidige løsninger","workaround"]},{"id":"knownerror","g":"run","word":"Kendt fejl","text":"Et problem, hvis årsag er forstået, men som endnu ikke er rettet, som regel med en midlertidig løsning skrevet ned. 🧩 Kendte fejl viser dem, så alle bruger den midlertidige løsning i stedet for at grave forfra.","also":["kendte fejl","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Trin-for-trin-instruktioner til at rette en kendt slags problem, så det gøres på samme måde, hurtigt, hver gang. Efter en stor hændelse kan teamet foreslå en, som du kan godkende.","also":["runbooks","driftsvejledning"]},{"id":"ci","g":"run","word":"Konfigurationselement","text":"Én ting, din service afhænger af, fx en server, et domæne, et certifikat, en nøgle eller en leverandør. 🗂️ Konfigurationselementer viser dem pr. service, så du kan se, hvad en hændelse påvirker, og hvad der skal fornys eller sikkerhedskopieres.","also":["konfigurationselementer"]},{"id":"expiry","g":"run","word":"Udløbsdato","text":"Den dato, hvor noget holder op med at virke, medmindre det fornyes, som et websteds sikkerhedscertifikat eller dets webadresse. AI-gile holder øje med de datoer og laver ét kort til hver fornyelse 30 dage i forvejen, så intet stopper uventet.","also":["udløbsdatoer","udløb","udløbsovervågning"]},{"id":"backup","g":"run","word":"Backup","text":"En gemt kopi af dine data fra tidligere, som du kan falde tilbage på, hvis noget går tabt eller bliver ødelagt. AI-gile tager en backup af dine tavler hver dag.","also":["backups","sikkerhedskopi","sikkerhedskopier"]},{"id":"restore","g":"run","word":"Gendannelse","text":"At lægge data tilbage fra en backup. En backup tæller først rigtigt, når du ved, at den kan gendannes, så det er værd at prøve det en gang imellem.","also":["gendan","gendannet","restore"]},{"id":"svcreview","g":"run","word":"Servicegennemgang","text":"Et tilbageblik på én måned af en service: åbnede og løste hændelser, hvor hurtigt folk fik svar, oppetid og brugte tokens. Den månedlige gennemgang viser det for hver service.","also":["servicegennemgange","månedlig gennemgang","månedlige gennemgange"]},{"id":"accessreview","g":"run","word":"Adgangsgennemgang","text":"Hver 90. dag at tjekke, hvem der stadig kan komme ind: delingslinks, venners roller og gemte adgangskoder og nøgler. Du beholder eller fjerner hver enkelt, så gammel adgang ikke bliver hængende.","also":["adgangsgennemgange"]},{"id":"improvements","g":"run","word":"Forbedringsliste","text":"Alt det, teamet har besluttet at blive bedre til, samlet ét sted: forslag fra retroen, handlinger fra gennemgange og løsninger på problemer, hver med sin status. Du finder den under 📈 Forbedringer.","also":["forbedringslister","forbedringer"]},{"id":"tokencap","g":"run","word":"Tokenloft","text":"En månedlig grænse for, hvor mange tokens en services agenter må bruge. Ved 80 % får du en advarsel; ved 100 % venter deres baggrundsarbejde til næste måned, eller til du hæver loftet.","also":["tokenlofter"]},{"id":"svcmgmt","g":"run","word":"Servicestyring","text":"Alt, der skal til for at holde en tjeneste nyttig og velfungerende for dem, der stoler på den, dag efter dag.","also":["service management","at passe en tjeneste"]},{"id":"itil","g":"run","word":"ITIL","text":"En udbredt vejledning i god servicestyring, der dækker blandt andet hændelser, problemer og ændringer. Navnet stod engang for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-servicestyring (ITSM)","text":"At drive teknologi som en tjeneste for mennesker, med klare måder at håndtere henvendelser, hændelser, ændringer og forbedringer på.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Administreret tjeneste (managed service)","text":"En tjeneste, som en anden driver og passer for dig, efter en aftale om, hvor godt den skal fungere.","also":["administrerede tjenester","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Tjenesteejer","text":"Personen, der står til ansvar for en tjeneste som helhed: hvor godt den fungerer, hvad den koster, og hvordan den forbedres.","also":["tjenesteejere","service owner","service owners"]},{"id":"sla","g":"run","word":"Serviceniveauaftale (SLA)","text":"Et skriftligt løfte til kunderne om, hvor godt en tjeneste vil fungere, for eksempel ”oppe 99,9 % af tiden” eller ”besvaret inden for en time”, ofte med penge tilbage, hvis løftet brydes.","also":["SLA","SLA'er","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Serviceniveaumål (SLO)","text":"Teamets eget mål for, hvor godt en tjeneste skal fungere over en periode, som regel sat lidt strengere end SLA'en for en sikkerheds skyld.","also":["SLO","SLO'er","SLOs"]},{"id":"sli","g":"run","word":"Serviceniveauindikator (SLI)","text":"Den faktiske måling, du holder op imod et mål, for eksempel andelen af besøg, der indlæstes uden problemer.","also":["SLI","SLI'er","SLIs"]},{"id":"availability","g":"run","word":"Tilgængelighed (af en tjeneste)","text":"Om folk kan bruge en tjeneste, når de har brug for den, ofte målt som oppetid.","also":["høj tilgængelighed","availability","high availability"]},{"id":"downtime","g":"run","word":"Nedetid (downtime)","text":"Tid, hvor en tjeneste ikke virker eller er slukket, planlagt eller ej.","also":["driftsstop","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Fejlbudget (error budget)","text":"Den lille mængde fejl, dit pålidelighedsmål tillader. Så længe der er noget tilbage, kan du tage chancer med ændringer; når det er brugt op, sætter du farten ned.","also":["fejlbudgetter","error budget","error budgets"]},{"id":"outage","g":"run","word":"Udfald (outage)","text":"Et tidsrum, hvor en tjeneste er nede eller fungerer meget dårligt for sine brugere.","also":["udfald","outage","outages","driftsforstyrrelse"]},{"id":"degraded","g":"run","word":"Forringet drift","text":"Virker, men dårligt: langsomt, eller med nogle dele, der ikke virker.","also":["forringet tjeneste","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Overvågning","text":"At holde øje med en tjeneste automatisk hele tiden, så problemer opdages, helst før brugerne mærker dem.","also":["monitorering","overvåget","monitoring"]},{"id":"observability","g":"run","word":"Observerbarhed","text":"Hvor godt du udefra kan se, hvad der foregår inde i et system, ved hjælp af dets logs, tal og spor.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log","text":"En løbende dagbog, et program fører over, hvad det gør, og som bruges til at finde ud af, hvad der gik galt.","also":["logs","logning","log","logging"],"noTip":1},{"id":"trace","g":"run","word":"Sporing (trace)","text":"En optegnelse over, hvordan én forespørgsel rejser gennem systemets forskellige dele, trin for trin, og som viser, hvor den blev langsom.","also":["spor","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Latenstid (forsinkelse)","text":"Hvor lang tid noget tager om at svare, for eksempel ventetiden, fra du klikker, til siden dukker op.","also":["latency"]},{"id":"alert","g":"run","word":"Alarm","text":"En automatisk besked om, at noget har brug for opmærksomhed, for eksempel at webstedet ikke svarer.","also":["alarmer","advarsel","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alarmtræthed","text":"Når der er så mange alarmer, at folk begynder at ignorere dem, også de vigtige.","also":["alert fatigue","alarm fatigue","alarmudmattelse"]},{"id":"dashboard","g":"run","word":"Dashboard (kontrolpanel)","text":"En skærm, der viser de vigtigste tal og tilstande med ét blik.","also":["dashboard","dashboards","kontrolpanel"],"noTip":1},{"id":"paging","g":"run","word":"Vagtalarmering (paging)","text":"At kalde på eller vække den vagthavende med det samme på grund af et problem.","also":["vagtalarm","paging","paged","ringe til vagten"]},{"id":"escalation","g":"run","word":"Eskalering","text":"At trække en med flere kompetencer eller mere beføjelse ind, når en sag ikke kan løses på det nuværende niveau, eller ikke hurtigt nok.","also":["eskalere","eskaleret","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage (sortering)","text":"Hurtigt at sortere indkommende sager efter, hvor hastende og vigtige de er, så det værste tages først.","also":["triagere","triage","triaged"]},{"id":"impact","g":"run","word":"Påvirkning (impact)","text":"Hvor meget noget påvirker folk: hvor mange, og hvor slemt.","noTip":1},{"id":"urgency","g":"run","word":"Hast (urgency)","text":"Hvor hurtigt noget skal håndteres. Påvirkning og hast sammen afgør prioriteten.","noTip":1},{"id":"plevels","g":"run","word":"Prioritetsniveauer (P1, P2…)","text":"Betegnelser for, hvor hastende en sag er. P1 er den mest alvorlige og kræver handling med det samme.","also":["P1","P2","P3","P4","prioritetsniveau"]},{"id":"queue","g":"run","word":"Sagskø","text":"Listen over henvendelser og hændelser, der venter på at blive taget.","also":["sagskøer","ticket queue","ticket queues","kø"]},{"id":"tiers","g":"run","word":"Første linje og anden linje","text":"Supportniveauer: første linje tager opkaldet og løser simple ting; anden linje har dybere kompetencer til de sværere ting. Kaldes også tier 1 og tier 2.","also":["første linje","anden linje","førstelinjesupport","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Hændelsesleder (incident commander)","text":"Den ene person, der leder indsatsen ved en hændelse, så alle ved, hvem der bestemmer, og hvem der gør hvad.","also":["hændelsesledere","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Svartid","text":"Hvor lang tid der går, før nogen første gang tager en henvendelse eller hændelse op.","also":["svartider","response time","response times"]},{"id":"resolution","g":"run","word":"Løsningstid","text":"Hvor lang tid det tager helt at få styr på en henvendelse eller hændelse, fra anmeldelse til rettet.","also":["løsningstider","tid til løsning","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Gennemsnitlig genoprettelsestid (MTTR)","text":"I gennemsnit, hvor lang tid det tager at få en tjeneste til at virke igen, efter at den er gået i stykker. MTTR kan betyde lidt forskellige ting, så sig, hvad du måler.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Gennemsnitlig tid mellem fejl (MTBF)","text":"I gennemsnit, hvor længe en tjeneste kører, før noget går i stykker.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Konfigurationsdatabase (CMDB)","text":"Listen over alle dine konfigurationselementer og hvordan de hænger sammen, så du kan se, hvad der afhænger af hvad.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Aktiv (asset)","text":"Alt af værdi, du ejer eller betaler for for at drive tjenesten, for eksempel en bærbar computer, en softwarelicens eller et domæne.","also":["aktiver","inventar","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Kapacitetsplanlægning","text":"At sikre, at der vil være nok computerkraft, lager og folk til det, der kommer.","also":["kapacitetsplan","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Skalering","text":"At klare flere brugere ved at give en maskine mere kraft (skalere op) eller tilføje flere maskiner (skalere ud).","also":["skalere op","skalere ud","skalering","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Forretningskontinuitet","text":"Planer for at holde det vigtige i gang, når noget stort går galt, for eksempel hvis et kontor, en nøgleleverandør eller computerne forsvinder.","also":["beredskabsplan","kontinuitetsplan","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Katastrofegenopretning (DR)","text":"Planen og værktøjerne til at få en tjeneste tilbage efter noget alvorligt, for eksempel at et helt datacenter går tabt.","also":["DR","disaster recovery","genopretning efter katastrofe"]},{"id":"rto","g":"run","word":"Mål for genoprettelsestid (RTO)","text":"Den længste tid, en tjeneste må være nede efter en katastrofe, før den skal virke igen.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Mål for genoprettelsespunkt (RPO)","text":"Hvor meget af de nyeste data du har råd til at miste, målt i tid. Et RPO på en time betyder sikkerhedskopier mindst hver time.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundans","text":"At have reserver klar, som en anden server, så én fejl ikke stopper tjenesten.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover (skift til reserve)","text":"At skifte over til et reservesystem af sig selv, når det sædvanlige svigter.","also":["failover","fail over","skift"]},{"id":"spof","g":"run","word":"Single point of failure (kritisk enkeltpunkt)","text":"Én del, der tager alt med sig, når den går i stykker, fordi der ikke er nogen reserve.","also":["SPOF","single points of failure","single point of failure"]},{"id":"maintwin","g":"run","word":"Vedligeholdelsesvindue","text":"Et planlagt tidsrum, hvor en tjeneste kan være sat på pause eller være langsom på grund af vedligeholdelse, og som varsles til brugerne på forhånd.","also":["vedligeholdelsesvinduer","planlagt vedligeholdelse","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Overdragelse","text":"At give arbejde, viden og ansvar videre til en anden person eller et andet team, så intet bliver tabt.","also":["overdragelser","handover","handovers"]},{"id":"kb","g":"run","word":"Vidensbase","text":"En samling hjælpeartikler og svar, til brugere og til teamet.","also":["vidensbaser","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Kundetilfredshed (CSAT)","text":"En score fra brugerne, der siger, hvor tilfredse de var, som man ofte beder om, når en henvendelse er lukket.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Leverandør","text":"Et eksternt firma, du er afhængig af, for eksempel din hostingudbyder. Kaldes også en vendor eller tredjepart.","also":["leverandører","tredjepart","vendor","vendors","supplier","suppliers","third party"],"noTip":1},{"id":"retire","g":"run","word":"Nedlæggelse af tjeneste","text":"At slukke for en tjeneste for altid, på en sikker måde: give brugerne besked, tage sig af data og adgang og få omkostningerne til at stoppe.","also":["nedlægge en tjeneste","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL, udgået)","text":"Når et produkt holder op med at få opdateringer eller support fra sin producent, så det bør udskiftes.","also":["EOL","end-of-life","end of life","udgået","udløbet levetid"]},{"id":"cybersec","g":"sec","word":"Cybersikkerhed","text":"At beskytte systemer og data mod at blive brudt ind i, stjålet eller beskadiget.","also":["it-sikkerhed","informationssikkerhed","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Autentificering","text":"At tjekke, hvem nogen er, som regel med en adgangskode eller en kode. Forkortes ofte authn.","also":["authn","login"]},{"id":"authz","g":"sec","word":"Autorisation (tilladelseskontrol)","text":"At tjekke, hvad nogen må gøre, når du først ved, hvem det er. Forkortes ofte authz.","also":["autorisering","tilladelse","authz","authorization"]},{"id":"mfa","g":"sec","word":"Multifaktorgodkendelse (MFA)","text":"At logge ind med to eller flere beviser, som en adgangskode plus en kode på telefonen. Kaldes også tofaktor (2FA).","also":["MFA","2FA","tofaktorgodkendelse","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"At logge ind én gang for at komme ind i mange systemer, som at bruge sin arbejdskonto overalt.","also":["SSO","enkelt login"]},{"id":"pwmgr","g":"sec","word":"Adgangskodemanager (password manager)","text":"En app, der laver stærke adgangskoder og husker dem for dig.","also":["adgangskodemanager","adgangskodehåndtering","password manager","password managers"]},{"id":"secret","g":"sec","word":"Hemmelighed (secret)","text":"En adgangskode, nøgle eller anden privat kode, som et program bruger for at komme ind et sted. Den må aldrig deles eller skrives ind i koden.","also":["hemmeligheder","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API-nøgle","text":"En hemmelig kode, der lader et program bruge en anden tjenestes API, og som viser, hvem der bruger (og betaler for) den.","also":["API-nøgler","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Adgangstoken (access token)","text":"Et midlertidigt adgangskort, der viser, at et program må komme ind, så det ikke behøver din adgangskode hver gang. Ikke det samme som et AI-token.","also":["adgangstokens","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Kryptering","text":"At omdanne information til volapyk, så kun den, der har den rette nøgle, kan læse den.","also":["krypteret","kryptere","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Den sikre måde, websider rejser på, som vises med hængelåsen i din browser, så ingen undervejs kan læse eller ændre dem."},{"id":"cert","g":"sec","word":"SSL/TLS-certifikat","text":"Et digitalt id-kort, der lader et websted bevise, hvem det er, og bruge HTTPS. Det udløber, så det skal fornyes.","also":["TLS-certifikat","SSL-certifikat","certifikat","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Tilladelser","text":"Reglerne for, hvem der må se eller ændre hvad.","also":["tilladelse","rettigheder","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mindst mulige rettigheder","text":"At give hver person eller hvert program kun den adgang, de virkelig har brug for, og kun så længe de har brug for den.","also":["least privilege","principle of least privilege","mindste privilegium"]},{"id":"rbac","g":"sec","word":"Rollebaseret adgang (RBAC)","text":"At give adgang efter rolle, som læser eller redaktør, i stedet for person for person.","also":["RBAC","role-based access","rollebaseret adgangskontrol"]},{"id":"vuln","g":"sec","word":"Sårbarhed","text":"En svaghed, som nogen kan udnytte til at bryde ind eller gøre skade.","also":["sårbarheder","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (nuldagssårbarhed)","text":"En svaghed, som angribere kender til, før producenterne har nået at rette den.","also":["zero-days","zero day","zero-day"]},{"id":"malware","g":"sec","word":"Skadelig software (malware)","text":"Skadelig software, som virus, lavet til at ødelægge, spionere eller stjæle.","also":["malware","skadeprogram"]},{"id":"ransomware","g":"sec","word":"Ransomware (løsepengevirus)","text":"Skadelig software, der låser dine filer og kræver penge for at låse dem op. Gode sikkerhedskopier er det bedste forsvar.","also":["ransomware","løsepengevirus","ransomware-angreb","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing (netfiskeri)","text":"Falske beskeder, der prøver at narre dig til at give adgangskoder eller penge fra dig, eller til at åbne noget skadeligt.","also":["phishing","netfiskeri","phishing-mail","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering (social manipulation)","text":"At narre mennesker, i stedet for computere, til at give adgang, for eksempel et falsk opkald fra ”IT-support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"En vagt, der afgør, hvilken netværkstrafik der må komme ind eller gå ud.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kort for virtuelt privat netværk: en privat, krypteret forbindelse over internettet, ofte brugt til at nå arbejdets systemer sikkert.","also":["virtuelt privat netværk","virtual private network"]},{"id":"ddos","g":"sec","word":"Overbelastningsangreb (DoS, DDoS)","text":"At oversvømme en tjeneste med så meget falsk trafik, at rigtige mennesker ikke kan bruge den. DDoS betyder, at den kommer fra mange computere på én gang.","also":["DoS","DDoS","denial of service","DDoS-angreb","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetrationstest (pentest)","text":"At hyre venligtsindede eksperter til at prøve at bryde ind, så svagheder bliver fundet, før rigtige angribere finder dem.","also":["pentest","pentests","pen test","pen testing","penetration testing"]},{"id":"audit","g":"sec","word":"Sikkerhedsgennemgang","text":"Et grundigt tjek af, hvor godt noget er beskyttet, ud fra en liste over god praksis.","also":["sikkerhedsaudit","sikkerhedsrevision","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Trusselsmodellering","text":"At tænke igennem, hvem der kan angribe noget, hvordan, og hvad du ville gøre for at stoppe dem.","also":["trusselsmodel","threat model","threat modelling","threat modeling"]},{"id":"breach","g":"sec","word":"Databrud","text":"Når private oplysninger kommer ud til folk, der ikke skal have dem, eller bliver mistet eller ændret uden tilladelse.","also":["datalæk","databrud","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Personoplysninger","text":"Alle oplysninger om en person, der kan identificeres, for eksempel et navn, en e-mailadresse eller et sted. På engelsk også kaldet PII.","also":["personoplysning","persondata","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR (databeskyttelsesforordningen)","text":"EU's lov om personoplysninger (Storbritannien har sin egen udgave): indsaml kun det, du har brug for, opbevar det sikkert, og lad folk se eller slette deres egne oplysninger.","also":["GDPR","databeskyttelsesforordningen","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Databeskyttelse","text":"At passe ordentligt på personoplysninger og inden for lovens rammer.","also":["databeskyttelseslov","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privatlivspolitik","text":"En offentlig side, der fortæller, hvilke personoplysninger du indsamler, hvorfor, og hvad du gør med dem.","also":["privatlivspolitikken","fortrolighedspolitik","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Samtykke","text":"En persons tydelige og frivillige ja til, at vedkommendes oplysninger bruges på en bestemt måde. Det kan trækkes tilbage når som helst.","also":["samtykker","opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"En lille fil, et websted gemmer i din browser for at huske ting, som at du er logget ind. Nogle kræver først dit samtykke.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Dataminimering","text":"Kun at indsamle og gemme de personoplysninger, du virkelig har brug for til opgaven.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Opbevaringstid","text":"Hvor længe data gemmes, før de slettes. At gemme dem højst så længe, som det er nødvendigt, er sikrere og ofte et lovkrav.","also":["sletning","opbevaringsperiode","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonymisering","text":"At ændre data, så ingen med rimelighed længere kan identificeres ud fra dem.","also":["anonymiseret","anonyme data","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisering","text":"At bytte navne og andre oplysninger ud med koder, med en nøgle gemt adskilt til at koble dem sammen igen. Det er stadig personoplysninger.","also":["pseudonymiseret","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Databehandleraftale (DPA)","text":"En kontrakt, der siger, hvordan en leverandør må behandle personoplysninger på dine vegne.","also":["DPA","databehandleraftalen","data processing agreement"]},{"id":"dpia","g":"sec","word":"Konsekvensanalyse for databeskyttelse (DPIA)","text":"Et grundigt blik, før du starter, på hvordan en plan om at bruge personoplysninger kan påvirke folk, og hvordan risiciene kan mindskes.","also":["DPIA","konsekvensanalyse","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Auditlog (revisionslog)","text":"En optegnelse over, hvem der gjorde hvad og hvornår, så handlinger kan tjekkes bagefter.","also":["revisionslog","logbog","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Overholdelse af regler (compliance)","text":"At følge de love, regler og standarder, der gælder for dig, og kunne vise, at du gør det.","also":["compliance","regeloverholdelse","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"En velkendt international standard for styring af informationssikkerhed. Virksomheder kan blive certificeret efter den.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"En amerikansk rapport, kontrolleret af eksterne revisorer, der viser, at en virksomhed passer ordentligt på kundedata.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"En AI, der arbejder på en opgave på egen hånd: læser koden, laver ændringer, kører tjek og melder tilbage. Dens arbejde bliver stadig tjekket.","also":["agenter","agents"]},{"id":"token","g":"ai","word":"Token","text":"De små stykker tekst, en AI læser og skriver, cirka tre fjerdedele af et ord hver. AI-brug tælles i tokens, så færre tokens levner mere af din plan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"En lille kommando, der kører af sig selv på et bestemt tidspunkt, for eksempel når en AI-session starter, så teamet hører dine kommentarer.","also":["hooks"]},{"id":"ai","g":"ai","word":"Kunstig intelligens (AI)","text":"Computersystemer, der gør ting, vi normalt tror kræver et menneske, som at skrive, svare på spørgsmål eller genkende billeder.","also":["AI","KI","kunstig intelligens","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Maskinlæring (ML)","text":"En måde at få computere til at lære mønstre ud fra mange eksempler i stedet for at give dem præcise regler.","also":["ML","machine learning","maskinlæring"]},{"id":"model","g":"ai","word":"Model","text":"AI-systemets trænede ”hjerne”, bygget ved at lære af et enormt antal eksempler. Modeller er forskellige i dygtighed, hastighed og pris.","also":["modeller","AI-model","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Stor sprogmodel (LLM)","text":"En AI-model, trænet på enorme mængder tekst, så den kan læse og skrive sprog.","also":["LLM","LLM'er","LLMs","sprogmodel","large language model"]},{"id":"genai","g":"ai","word":"Generativ AI","text":"AI, der skaber nye ting, som tekst, billeder eller kode, i stedet for kun at sortere eller opdage dem.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Et program, du taler med på almindeligt sprog, ved at skrive eller tale.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Det, du giver en AI: dit spørgsmål eller dine instruktioner, plus alt, du rækker den. Tydeligere prompts giver som regel bedre svar.","also":["prompts","prompter","instruktion"]},{"id":"prompteng","g":"ai","word":"Promptdesign (prompt engineering)","text":"Kunsten at skrive prompts, der giver pålidelige, brugbare resultater.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Systemprompt","text":"Baggrundsinstruktioner, en AI får, før samtalen begynder, og som fastlægger dens rolle og regler. De vejer tungere end det, du skriver.","also":["systemprompts","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kontekst","text":"Alt, AI'en kan se, mens den arbejder: instruktionerne, dine beskeder, filer, den har læst, og tidligere svar.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekstvindue","text":"Hvor meget en AI kan holde i hovedet på én gang, målt i tokens. Ud over det bliver ældre dele smidt ud eller opsummeret.","also":["kontekstvinduet","context window","context windows"]},{"id":"session","g":"ai","word":"Session","text":"Én arbejdssamtale med en AI, fra start til slut. En ny session begynder med en frisk hukommelse.","also":["sessioner","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Hukommelse","text":"Noter, en AI gemmer mellem sessioner, så den husker dine præferencer og tidligere beslutninger.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"Når en AI siger noget, der lyder sikkert, men er opdigtet eller forkert. Tjek vigtige fakta.","also":["hallucinationer","hallucinere","hallucinerer","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Træning","text":"At lære en model noget ved at vise den et enormt antal eksempler, før nogen bruger den.","also":["trænet","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Træningsdata","text":"De eksempler, en model lærte af. Dens viden ender på den dato, hvor materialet blev indsamlet.","also":["træningsmateriale","training data","training set"]},{"id":"cutoff","g":"ai","word":"Vidensgrænse (knowledge cutoff)","text":"Den dato, hvor en AI's indbyggede viden ender. Den kender ikke til senere ting, medmindre den slår dem op.","also":["vidensdato","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Finjustering (fine-tuning)","text":"Ekstra træning af en eksisterende model på dine egne eksempler, for at gøre den bedre til én bestemt opgave.","also":["finjustere","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferens (inference)","text":"At en AI-model rent faktisk bruges til at svare på noget, i modsætning til at blive trænet.","also":["inference","inferens","model inference"]},{"id":"tooluse","g":"ai","word":"Værktøjsbrug (tool use)","text":"At en AI kan gøre ting og ikke bare tale: køre kommandoer, læse filer eller søge på nettet, gennem værktøjer, appen giver den.","also":["værktøjskald","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Underagent (subagent)","text":"En hjælpe-AI, som en hoved-AI giver en mindre opgave og får resultatet tilbage fra.","also":["underagenter","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multiagent","text":"Flere AI'er, der arbejder sammen om det samme arbejde, hver med sin del, som et lille team.","also":["flere agenter","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Selvstændighed (autonomi)","text":"Hvor meget en AI må gøre på egen hånd, før den skal spørge et menneske.","also":["autonomi","autonom","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop (et menneske med i processen)","text":"At have et menneske med, der tjekker eller godkender, hvad AI'en gør, på afgørende punkter. I AI-gile er det dig.","also":["human in the loop","human-in-the-loop","HITL","menneske i løkken"]},{"id":"guardrails","g":"ai","word":"Autoværn (guardrails)","text":"Grænser og tjek, der holder en AI's handlinger sikre, som at kræve godkendelse, før noget går live. De mindsker risikoen for fejl, men udelukker dem ikke.","also":["autoværn","guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"At lade en AI slå ting op i dine egne dokumenter, før den svarer, så dens svar bygger på dine fakta.","also":["RAG","retrieval augmented generation","søgeforstærket generering"]},{"id":"embedding","g":"ai","word":"Indlejring (embedding)","text":"At gøre tekst til en liste af tal, der fanger dens betydning, så en computer kan finde ting, der betyder noget lignende.","also":["indlejringer","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Vektordatabase","text":"En database bygget til at søge i den slags talrækker (indlejringer) for at finde materiale med lignende betydning.","also":["vektordatabaser","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"En fælles måde at koble værktøjer og datakilder til AI-apps, så en AI kan bruge dem.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatur","text":"En indstilling for, hvor eventyrlystne en AI's svar er. Lav giver mere stabile, forudsigelige svar; høj giver mere varierede. Ingen af dem gør, at den altid har ret.","also":["modeltemperatur","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"I stand til at arbejde med mere end én slags information, som tekst, billeder og lyd.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Evaluering (eval)","text":"En planlagt test af, hvor godt en AI klarer udvalgte eksempler, så du kan sammenligne modeller eller prompts.","also":["eval","evals","evalueringer"]},{"id":"bias","g":"ai","word":"Skævhed (bias)","text":"Når en AI (eller et menneske) uretfærdigt hælder til den ene side, ofte på grund af det, den har lært af.","also":["bias","fordom","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Ansvarlig AI","text":"At bruge AI retfærdigt, sikkert og ærligt, hvor mennesker stadig står til ansvar for resultaterne.","also":["etisk AI","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Promptinjektion (prompt injection)","text":"Et trick, hvor skjulte instruktioner på en webside eller i en fil prøver at få en AI til at gøre noget, brugeren ikke har bedt om.","also":["prompt injection","prompt injections","promptinjektioner"]},{"id":"ratelimit","g":"ai","word":"Hastighedsgrænse (rate limit)","text":"Et loft over, hvor mange forespørgsler du må sende til en tjeneste på en bestemt tid. Går du over, må du vente.","also":["rate limit","rate limits","rate limited","kaldsgrænse"]},{"id":"usagelimit","g":"ai","word":"Forbrugsgrænse","text":"Hvor meget AI-arbejde din plan tillader i en periode, hvorefter det sættes på pause eller koster mere.","also":["forbrugsgrænser","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"At bygge software mest ved at beskrive, hvad du vil have, til en AI og lade den skrive koden.","also":["vibe-coding","vibekodning"]},{"id":"budget","g":"money","word":"Budget","text":"Det beløb, der er sat af til noget.","also":["budgetter","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Omkostningsoverslag","text":"Et bedste bud på, hvad noget kommer til at koste, før du går i gang.","also":["prisoverslag","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Afkast af investering (ROI)","text":"Hvad du får tilbage i forhold til, hvad du puttede i. Er det positivt, var det det værd.","also":["ROI","return on investment","afkast"]},{"id":"tco","g":"money","word":"Samlede ejeromkostninger (TCO)","text":"Alt, noget i virkeligheden koster over hele sin levetid, ikke bare prisen for at købe det: drift, support, opgraderinger og til sidst nedlæggelse.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx og OpEx","text":"CapEx er penge brugt på forhånd på ting, du beholder; OpEx er løbende udgifter, som månedlige regninger.","also":["CapEx","OpEx","investeringsomkostning","driftsomkostning","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonnement","text":"At betale regelmæssigt, som regel hver måned eller hvert år, for at blive ved med at bruge noget.","also":["abonnementer","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software som en tjeneste (SaaS)","text":"Software, du bruger online og betaler for med abonnement, mens producenten driver den for dig.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Betal for det, du bruger","text":"Kun at betale for det, du bruger, som med cloud computing eller AI-tokens.","also":["pay as you go","pay-as-you-go","forbrugsbaseret prissætning","usage-based pricing"]},{"id":"overage","g":"money","word":"Overforbrug","text":"Brug ud over det, din plan omfatter, hvilket kan koste ekstra.","also":["overskridelse","ekstragebyr","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Udgiftsalarm","text":"En besked, når forbruget eller brugen når et niveau, du har valgt. Den advarer dig, men stopper ikke altid yderligere opkrævninger.","also":["faktureringsalarm","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Gratis niveau","text":"Et gratis niveau af en betalingstjeneste, med begrænsninger. Praktisk til at komme i gang.","also":["gratis plan","free tier","free plan"]},{"id":"pricing","g":"money","word":"Prisplan","text":"De forskellige pakker, en tjeneste sælger, hver med sin egen pris og sine egne grænser.","also":["prisplaner","prismodel","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licens","text":"Reglerne for, hvordan du må bruge, kopiere, ændre eller dele noget, en anden har lavet, som software, skrifttyper eller billeder.","also":["licenser","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software, hvis kode alle kan læse, bruge og ofte ændre gratis, efter licensens regler.","also":["open source","open-source","åben kildekode","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source-licens","text":"Reglerne, der følger med open source-kode. Nogle lader dig gøre næsten, hvad som helst (som MIT); andre kræver, at du også deler dine ændringer (som GPL).","also":["open source-licenser","MIT-licens","GPL","open source licence","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Proprietær","text":"Ejet af et firma og ikke frit at kopiere eller ændre. Det modsatte af open source.","also":["proprietær software","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Ophavsret","text":"Skaberens lovlige ret til at bestemme over kopier af sit værk, herunder kode og tekst.","also":["copyright","ophavsretligt beskyttet","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Immaterielle rettigheder (IP)","text":"Idéer og skabelser, som loven ser som ejede, som kode, design, navne og logoer.","also":["immaterialret","IP","intellectual property"]},{"id":"tos","g":"money","word":"Brugsvilkår","text":"Reglerne, du går med til, når du bruger en tjeneste.","also":["vilkår","almindelige vilkår","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Kontrakt","text":"En skriftlig aftale mellem to parter, som loven står bag.","also":["aftale","aftaler","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Arbejdsbeskrivelse (SOW)","text":"Et dokument, der præcist beskriver, hvilket arbejde der skal udføres, inden hvornår og for hvor meget.","also":["SOW","statement of work","opgavebeskrivelse"]},{"id":"fixedprice","g":"money","word":"Fast pris","text":"En aftalt pris for hele opgaven, uanset hvor lang tid den tager.","also":["fastpris","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Løbende afregning","text":"At betale for de timer, der rent faktisk er arbejdet, og de ting, der rent faktisk er brugt, i stedet for en fast pris.","also":["T&M","time and materials","timepris"]},{"id":"invoice","g":"money","word":"Faktura","text":"En regning, der beder om betaling for udført arbejde eller leverede varer.","also":["fakturaer","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Leverandørlåsning (vendor lock-in)","text":"Når det er så svært eller dyrt at skifte væk fra en leverandør, at du sidder fast.","also":["låsning","lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Indkøb","text":"Processen med at vælge og købe hos leverandører.","also":["udbud","procurement"]},{"id":"servicecredit","g":"money","word":"Servicekredit","text":"Penge tilbage eller rabat, du får, når en leverandør ikke holder sin SLA.","also":["servicekreditter","service credit","service credits"]}]}};
